wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(93387201442701825)
,p_plug_name=>'Cards'
,p_parent_plug_id=>wwv_flow_imp.id(93387091094701824)
,p_region_template_options=>'#DEFAULT#:margin-bottom-lg'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(86236996114821533)
,p_plug_display_sequence=>10
,p_plug_display_point=>'SUB_REGIONS'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('SELECT COUNT(1) || DECODE(NVL(:P_LANG, ''ar''), ''ar'', '' \0645\0632\0627\062F '', '' Auction '') AS COUNT,'),
unistr('       DECODE(NVL(:P_LANG, ''ar''), ''ar'', ''\0627\0644\0645\0632\0627\062F\0627\062A'', ''Auctions'') AS TITLE,'),
'       ''alarm-clock'' AS ICON,',
'       ''auctions'' AS TYPE,',
'       1 AS SEQ,',
'       5 AS PAGE_NUMBER',
'  FROM AUCTIONS',
'UNION ALL',
unistr('SELECT COUNT(1) ||  DECODE(NVL(:P_LANG, ''ar''), ''ar'', '' \0645\0646\062A\062C '', '' Product '') AS COUNT,'),
unistr('       DECODE(NVL(:P_LANG, ''ar''), ''ar'', ''\0627\0644\0645\0646\062A\062C\0627\062A'', ''Products'') AS TITLE,'),
'       ''package'' AS ICON,',
'       ''products'' AS TYPE,',
'       2 AS SEQ,',
'       5 AS PAGE_NUMBER',
'  FROM PRODUCTS',
'UNION ALL',
unistr('SELECT COUNT(1) ||  DECODE(NVL(:P_LANG, ''ar''), ''ar'', '' \0645\0632\0627\062F \0642\0627\0626\0645 '', '' Active Auction '') AS COUNT,'),
unistr('       DECODE(NVL(:P_LANG, ''ar''), ''ar'', ''\0627\0644\0645\0632\0627\062F\0627\062A \0627\0644\0642\0627\0626\0645\0629'', '' Active Auctions '') AS TITLE,'),
'       ''clock-o'' AS ICON,',
'       ''current_auctions'' AS TYPE,',
'       3 AS SEQ,',
'       5 AS PAGE_NUMBER',
'  FROM AUCTIONS',
' WHERE START_DATE > SYSDATE',
'   AND END_DATE IS NULL',
'UNION ALL',
unistr('SELECT COUNT(1) ||  DECODE(NVL(:P_LANG, ''ar''), ''ar'', '' \0645\0632\0627\062F \0645\0646\062A\0647\064A '', '' Ended Auction '') AS COUNT,'),
unistr('       DECODE(NVL(:P_LANG, ''ar''), ''ar'', ''\0627\0644\0645\0632\0627\062F\0627\062A \0627\0644\0645\0646\062A\0647\064A\0629'', '' Ended Auctions '') AS TITLE,'),
'       ''check-circle-o'' AS ICON,',
'       ''ended_auctions'' AS TYPE,',
'       4 AS SEQ,',
'       5 AS PAGE_NUMBER',
'  FROM AUCTIONS',
' WHERE IS_ENDED = 1',
'UNION ALL',
unistr('SELECT COUNT(1) ||  DECODE(NVL(:P_LANG, ''ar''), ''ar'', '' \062A\0627\062C\0631 '', '' Seller '') AS COUNT,'),
unistr('       DECODE(NVL(:P_LANG, ''ar''), ''ar'', ''\0627\0644\062A\062C\0627\0631'', ''Sellers'') AS TITLE,'),
'       ''users'' AS ICON,',
'       ''ended_auctions'' AS TYPE,',
'       5 AS SEQ,',
'       5 AS PAGE_NUMBER',
'  FROM SELLERS',
' ORDER BY SEQ;'))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_CARDS'
,p_plug_query_num_rows_type=>'SCROLL'
,p_show_total_row_count=>false
);
