,p_plug_name=>'Request Type  2'
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(86236996114821533)
,p_plug_display_sequence=>40
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT COUNT(1) AS COUNT,',
'        ''Pending'' AS REQUEST_STATUS,',
'        NULL AS STATUS_ID',
'   FROM SELLERS',
'  WHERE REQUEST_STATUS_ID = LOOKUPS_MNT.lookup_detail_id_by_code (p_lookup_detail_code => ''pending'', p_lookup_code  => ''request_status'')',
'   AND ID in (SELECT seller_id FROM SELLER_CATEGORIES WHERE CATEGORY_ID = SELLERS_REQ.category_id_by_employee_id (p_employee_id  => 4))',
'    OR SELLER_TYPE_ID IN (:P2_GOVERMENTAL_ID,:P2_OTHER_ID)',
'--  GROUP BY REQUEST_STATUS_ID',
'UNION ALL',
'SELECT COUNT(1) AS COUNT,',
'        ''Rejected'' AS REQUEST_STATUS,',
'        NULL AS STATUS_ID',
'   FROM SELLERS',
'  WHERE REQUEST_STATUS_ID = LOOKUPS_MNT.lookup_detail_id_by_code (p_lookup_detail_code => ''rejected'', p_lookup_code  => ''request_status'')',
'   AND ID in (SELECT seller_id FROM SELLER_CATEGORIES WHERE CATEGORY_ID = SELLERS_REQ.category_id_by_employee_id (p_employee_id  => 4))',
'    OR SELLER_TYPE_ID IN (:P2_GOVERMENTAL_ID,:P2_OTHER_ID)',
'--  GROUP BY REQUEST_STATUS_ID',
'UNION ALL',
'SELECT COUNT(1) AS COUNT,',
'        ''Approved'' AS REQUEST_STATUS,',
'        REQUEST_STATUS_ID AS STATUS_ID',
'   FROM SELLERS',
'  WHERE REQUEST_STATUS_ID = LOOKUPS_MNT.lookup_detail_id_by_code (p_lookup_detail_code => ''approved'', p_lookup_code  => ''request_status'')',
'   AND ID in (SELECT seller_id FROM SELLER_CATEGORIES WHERE CATEGORY_ID = SELLERS_REQ.category_id_by_employee_id (p_employee_id  => 4))',
'    OR SELLER_TYPE_ID IN (:P2_GOVERMENTAL_ID,:P2_OTHER_ID)',
' GROUP BY REQUEST_STATUS_ID'))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_CARDS'
,p_ajax_items_to_submit=>'P2_STATUS_ID'
,p_plug_query_num_rows_type=>'SCROLL'
