wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(128218004512865983)
,p_plug_name=>'Requests Type Report'
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(86286645774821557)
,p_plug_display_sequence=>30
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT s.ID,',
'       ''<img src="''|| s.AVATAR_URL ||''" alt="Logo Image" class="logo-image" style="width:25px;height:25px;" />'' AS LOGO_IMAGE,',
'       s.SELLER_TYPE_ID,',
'       s.IDENTITY_NUMBER AS CR_NO,',
'       DECODE(:P_LANG, ''ar'',s.TRADE_NAME_AR, s.TRADE_NAME_EN) AS ENTITY_NAME,',
'       s.TAX_NUMBER,',
'       s.OTHER_SELLER_TYPE,',
'       s.PENDING_TYPE_ID,',
'       s.REQUEST_STATUS_ID,',
'       s.CREATED_DATE,',
'       d.APPLICANT_TYPE_ID,',
'       d.APPLICANT_NAME,',
'       d.APPLICANT_EMAIL,',
'       d.APPLICANT_PHONE_NUMBER',
'  FROM SELLERS s,',
'       SELLERS_REQUESTS_DETAILS d',
' WHERE (s.REQUEST_STATUS_ID = :P2_STATUS_ID OR :P2_STATUS_ID IS NULL)',
'   AND s.ID = d.SELLER_ID (+)',
'   AND (s.ID in (SELECT seller_id FROM SELLER_CATEGORIES WHERE CATEGORY_ID = SELLERS_REQ.category_id_by_employee_id (p_employee_id  => :P_EMP_ID)) OR SELLER_TYPE_ID IN (:P2_GOVERMENTAL_ID,:P2_OTHER_ID))',
'  ORDER BY s.ID DESC;'))
,p_plug_source_type=>'NATIVE_IR'
,p_ajax_items_to_submit=>'P2_STATUS_ID'
,p_prn_content_disposition=>'ATTACHMENT'
