wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(25518295897281513)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Upload Files'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_file_names        APEX_T_VARCHAR2;',
'    l_file              APEX_APPLICATION_TEMP_FILES%ROWTYPE;',
'    l_file_name         VARCHAR2(255);',
'    l_request_url	    VARCHAR2(32767);',
'    l_result	        CLOB;',
'    l_request_filename	VARCHAR2(500);',
'    l_inner_folder  	VARCHAR2(500);',
'    v_item_name         VARCHAR2(255);',
'    ',
'    type itemsarray IS VARRAY(8) OF VARCHAR2(500);',
'    items_names itemsarray;',
'    items itemsarray;',
'    total integer;',
'BEGIN',
'    IF :P3_SELLER_TYPE NOT IN (:P3_IS_GOV, :P3_IS_OTHER) THEN',
'        IF :P3_APPLICANT_TYPE = :P3_IS_AUTHORIZED THEN',
'            IF :P3_MANAGER_IS_EMP = 1 THEN',
'                items := itemsarray(:P3_SELLER_CR_FILE, :P3_SELLER_NATIONAL_ADDRESS_FILE, :P3_SELLER_ADMIN_ID_FILE, :P3_SELLER_IBAN_FILE, :P3_SELLER_TAX_FILE, :P3_SELLER_LOGO_FILE, :P3_APPLICANT_AUTHORIZATION_FILE);',
'                items_names := itemsarray(''P3_SELLER_CR_FILE'', ''P3_SELLER_NATIONAL_ADDRESS_FILE'', ''P3_SELLER_ADMIN_ID_FILE'', ''P3_SELLER_IBAN_FILE'', ''P3_SELLER_TAX_FILE'', ''P3_SELLER_LOGO_FILE'', ''P3_APPLICANT_AUTHORIZATION_FILE'');',
'            ELSE',
'                items := itemsarray(:P3_SELLER_CR_FILE, :P3_SELLER_NATIONAL_ADDRESS_FILE, :P3_SELLER_ADMIN_ID_FILE, :P3_SELLER_IBAN_FILE, :P3_SELLER_TAX_FILE, :P3_SELLER_LOGO_FILE, :P3_APPLICANT_AUTHORIZATION_FILE, :P3_ADMIN_AUTHORIZATION_FILE);',
'                items_names := itemsarray(''P3_SELLER_CR_FILE'', ''P3_SELLER_NATIONAL_ADDRESS_FILE'', ''P3_SELLER_ADMIN_ID_FILE'', ''P3_SELLER_IBAN_FILE'', ''P3_SELLER_TAX_FILE'', ''P3_SELLER_LOGO_FILE'', ''P3_APPLICANT_AUTHORIZATION_FILE'', ''P3_ADMIN_AUTHORIZATIO'
||'N_FILE'');',
'            END IF;',
'        ELSIF :P3_APPLICANT_TYPE <> :P3_IS_AUTHORIZED AND :P3_MANAGER_IS_EMP = 1 THEN',
'            items := itemsarray(:P3_SELLER_CR_FILE, :P3_SELLER_NATIONAL_ADDRESS_FILE, :P3_SELLER_ADMIN_ID_FILE, :P3_SELLER_IBAN_FILE, :P3_SELLER_TAX_FILE, :P3_SELLER_LOGO_FILE);',
'            items_names := itemsarray(''P3_SELLER_CR_FILE'', ''P3_SELLER_NATIONAL_ADDRESS_FILE'', ''P3_SELLER_ADMIN_ID_FILE'', ''P3_SELLER_IBAN_FILE'', ''P3_SELLER_TAX_FILE'', ''P3_SELLER_LOGO_FILE'');',
'        ELSIF :P3_APPLICANT_TYPE <> :P3_IS_AUTHORIZED AND :P3_MANAGER_IS_EMP = 0 THEN',
'            items := itemsarray(:P3_SELLER_CR_FILE, :P3_SELLER_NATIONAL_ADDRESS_FILE, :P3_SELLER_ADMIN_ID_FILE, :P3_SELLER_IBAN_FILE, :P3_SELLER_TAX_FILE, :P3_SELLER_LOGO_FILE, :P3_ADMIN_AUTHORIZATION_FILE);',
'                items_names := itemsarray(''P3_SELLER_CR_FILE'', ''P3_SELLER_NATIONAL_ADDRESS_FILE'', ''P3_SELLER_ADMIN_ID_FILE'', ''P3_SELLER_IBAN_FILE'', ''P3_SELLER_TAX_FILE'', ''P3_SELLER_LOGO_FILE'', ''P3_ADMIN_AUTHORIZATION_FILE'');',
'        END IF;',
'',
'        total := items.count; ',
'',
'        FOR i in 1 .. total LOOP',
'            l_file_names := apex_string.SPLIT (',
'                                p_str => items(i),',
'                                p_sep => '':'' );',
'',
'            -- IF l_file_names.count = 0 THEN',
unistr('            --     RAISE_APPLICATION_ERROR(-20001, ''\064A\062C\0628 \0639\0644\064A\0643 \0631\0641\0639 \062C\0645\064A\0639 \0627\0644\0645\0644\0641\0627\062A'' || '' Count => '' || l_file_names.count || '' Item => '' || items(i));'),
'            -- END IF;',
'',
'            BEGIN',
'                SELECT *',
'                  INTO l_file',
'                  FROM APEX_APPLICATION_TEMP_FILES',
'                 WHERE NAME = items(i)',
'                   AND APPLICATION_ID = :APP_ID;',
'            EXCEPTION',
'                WHEN NO_DATA_FOUND THEN',
'                RAISE_APPLICATION_ERROR(-20002, ''NO DATA FOUND -> '' || items(i) || '' '' || items_names(i));',
'            END;',
'',
'            l_file_name := TO_CHAR(get_current_date, ''YY'') ',
'                           || DBMS_RANDOM.STRING(''x'', 8)',
'                           || SYSTEM_CONTROLS.file_extension_by_mimetype(p_mimetype => l_file.MIME_TYPE);',
'',
'            l_request_url := :G_OCI_BASE_URL||''/b/seller_signup/o/''|| l_file_name;',
'            ',
'            l_result := APEX_WEB_SERVICE.make_rest_request (',
'                            p_url                  => l_request_url,',
'                            p_http_method          => ''PUT'',',
'                            p_body_blob            => l_file.BLOB_CONTENT,',
'                            p_credential_static_id => ''OCI_AUTH''',
'                        );',
'',
'            IF APEX_WEB_SERVICE.g_status_code NOT IN ( 200, 201, 202, 203, 204, 205, 206, 207, 226 ) THEN',
'                SYSTEM_CONTROLS.ERROR_LOGS(p_ERROR_TYPE    => ''SYSTEM_ERROR'',',
'                                           p_PROCESS_NAME  => ''OCI_OS.put_object - '' || items(i),',
'                                           p_ERROR_CODE    => -2,',
'                                           p_ERROR_MESSAGE => SUBSTR(l_result, 1, 4000),',
'                                           p_logger_name   => :APP_USER);',
'                RAISE_APPLICATION_ERROR(-20003, ''Error with uploading Data!'');',
'            END IF;',
'',
'            SELECT item_name',
'              INTO v_item_name',
'              FROM APEX_APPLICATION_PAGE_ITEMS',
'             WHERE APPLICATION_ID = :APP_ID',
'               AND PAGE_ID = :APP_PAGE_ID',
'               AND item_name LIKE ''%'' || items_names(i) || ''_URL%'';',
'',
'            APEX_UTIL.SET_SESSION_STATE (v_item_name, l_request_url);',
'        END LOOP;',
'    END IF;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(25482166308281472)
,p_internal_uid=>9232163510031111
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(25517505493281511)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Create Seller'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE ',
'    v_result SELLERS_REQ.function_result;',
'BEGIN',
'    v_result := SELLERS_REQ.CREATE_SIGNUP_REQUEST (',
'                    p_seller_type      => :P3_SELLER_TYPE,',
'                    p_seller_other     => :P3_SELLER_OTHER,',
'                    p_tradename_ar     => :P3_SELLER_TRADENAME_AR,',
'                    p_tradename_en     => :P3_SELLER_TRADENAME_EN,',
'                    p_applicant_name   => :P3_APPLICANT_NAME,',
'                    p_phone_number     => :P3_APPLICANT_PHONE,',
'                    p_email            => :P3_APPLICANT_EMAIL,',
'                    p_cr_number        => :P3_SELLER_CR_NUMBER,',
'                    p_tax_number       => :P3_SELLER_TAX_NUMBER,',
'                    p_country_id       => :P3_SELLER_COUNTRY,',
'                    p_applicant_type   => :P3_APPLICANT_TYPE,',
'                    p_cities           => :P3_SELLER_CITIES,',
'                    p_activities       => :P3_SELLER_CATEGORIES,',
'                    p_bank_id          => :P3_SELLER_BANK,',
'                    p_currency_id      => :P3_SELLER_CURRENCY,',
'                    p_iban             => :P3_SELLER_IBAN,',
'                    p_bank_acc_name    => :P3_SELLER_ACCOUNT_NAME,',
'                    p_bank_acc_num     => :P3_SELLER_ACCOUNT_NUMBER,',
'                    p_admin_name       => :P3_ADMIN_NAME,',
'                    p_admin_natid      => :P3_ADMIN_ID_NUMBER,',
'                    p_admin_idtype_id  => :P3_ADMIN_ID_TYPE,',
'                    p_admin_job        => :P3_ADMIN_JOB,',
'                    p_admin_email      => :P3_ADMIN_EMAIL,',
'                    p_admin_phone      => :P3_ADMIN_PHONE,',
'                    p_mnger_name       => :P3_MANAGER_NAME,',
'                    p_mnger_natid      => :P3_MANAGER_ID_NUMBER,',
'                    p_mnger_idtype_id  => :P3_MANAGER_ID_TYPE,',
'                    p_mnger_job        => :P3_MANAGER_JOB,',
'                    p_mnger_email      => :P3_MANAGER_EMAIL,',
'                    p_mnger_phone      => :P3_MANAGER_PHONE,',
'                    p_mnger_is_admin   => :P3_MANAGER_IS_EMP,',
'                    p_iban_url         => :P3_SELLER_IBAN_FILE_URL,',
'                    p_cr_url           => :P3_SELLER_CR_FILE_URL,',
'                    p_tax_url          => :P3_SELLER_TAX_FILE_URL,',
'                    p_nat_address_id_url => :P3_SELLER_NATIONAL_ADDRESS_FILE_URL,',
'                    p_logo_url           => :P3_SELLER_LOGO_FILE_URL,',
'                    p_admin_id_url       => :P3_SELLER_ADMIN_ID_FILE_URL,',
'                    p_admin_auth_url     => :P3_ADMIN_AUTHORIZATION_FILE_URL,',
'                    p_applicant_auth_url => :P3_APPLICANT_AUTHORIZATION_FILE_URL,',
'                    p_lang               => NVL(:P_LANG, ''ar'')',
'                );',
'',
'    IF v_result.code <> 1 THEN',
'        RAISE_APPLICATION_ERROR(-20001, v_result.code || '' - '' || v_result.message);',
'    END IF;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(25482166308281472)
