wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(65109715091392659)
,p_process_sequence=>30
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Edit auction details'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_result                              VARCHAR2(5000);',
'    l_message                             VARCHAR2(5000);',
'    l_insurance_deducted                  VARCHAR2(255);',
'    l_trsyah                              VARCHAR2(255);',
'    l_sanad_billing_type       VARCHAR2(255);',
'    l_is_auto_generate_commission_invoice VARCHAR2(255);',
'    l_is_winning_price_has_vat            VARCHAR2(255);',
'    header                                json_object_t;',
'BEGIN',
'    header          := json_object_t();',
'',
'    IF :P8_INSURANCE_DEDUCTED = 1 THEN l_insurance_deducted := ''TRUE''; ELSE l_insurance_deducted := ''FALSE''; END IF;',
'    IF :P8_TRSYAH = 1 THEN l_trsyah := ''TRUE''; ELSE l_trsyah := ''FALSE''; END IF;',
'    IF :P8_SANAD_BILLING_TYPE = 1 THEN l_sanad_billing_type := ''TRUE''; ELSE l_sanad_billing_type := ''FALSE''; END IF;',
'    IF :P8_IS_WINNING_PRICE_HAS_VAT = 1 THEN l_is_winning_price_has_vat := ''TRUE''; ELSE l_is_winning_price_has_vat := ''FALSE''; END IF;',
'',
'    header.put(''category'',                      TRIM(:P8_CATEGORY_ID));',
'    header.put(''auctionHost'',                   TRIM(UPPER(LOOKUPS_MNT.lookup_detail_code_by_id (p_lookup_detail_id => :P8_DEPENDENT))));',
'    header.put(''insurance_deducted'',            TRIM(l_insurance_deducted));',
'    header.put(''autoAwarding'',                  TRIM(l_trsyah));',
'    header.put(''autoGenerateFullInvoice'',       TRIM(l_sanad_billing_type));',
'    header.put(''winningPriceHasVat'',            TRIM(l_is_winning_price_has_vat));',
'    header.put(''insuranceMethods'',              TRIM(UPPER(LOOKUPS_MNT.lookup_detail_code_by_id (p_lookup_detail_id => :P8_INSURANCE_METHOD))));',
'    header.put(''commission'',                    TRIM(:P8_COMMISSION));',
'    header.put(''commissionType'',                TRIM(UPPER(LOOKUPS_MNT.lookup_detail_code_by_id (p_lookup_detail_id => :P8_COMMISSION_TYPE_ID))));',
'    header.put(''nameAr'',                        TRIM(:P8_NAME_AR));',
'    header.put(''imageUrl'',                      TRIM(:P8_LOGO_URL));',
'    header.put(''brochure'',                      TRIM(:P8_BROCHURE_URL));',
'    header.put(''videoUrl'',                      TRIM(:P8_VIDEO_URL));',
'    header.put(''termsAndConditionsAr'',          TRIM(:P8_TERMS_AR));',
'',
'    -- INSERT INTO EMP ( ENAME, REQUEST ) VALUES ( ''edit_auction'', header.to_clob() );',
'',
'    l_result := SYSTEM_INTEGRATION.edit_auction (',
'                        p_body     => header.to_clob(),',
'                        p_id       => ''6593e6f1b7308c21881aaea3'',',
'                        p_message  => l_message',
'                    );',
'',
'    IF l_result <> ''1'' THEN',
'        RAISE_APPLICATION_ERROR(-20003, l_message);',
'    END IF;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_process_error_message=>'#SQLERRM_TEXT#'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(65098118900392635)
,p_process_when=>'P8_TYPE'
,p_process_when_type=>'VAL_OF_ITEM_IN_COND_EQ_COND2'
,p_process_when2=>'EditAuction'
,p_process_success_message=>'SUCCESS'
,p_internal_uid=>48823582704142257
);
