'    END IF;',
'    UPDATE INDIVIDUAL_PORTABLE_REQUESTS',
'       SET REJECT_REASON   = :P8_DECLINE_REASON,',
'           REQUEST_STATUS  = LOOKUPS_MNT.lookup_detail_id_by_code (p_lookup_detail_code => ''done'', p_lookup_code => ''individuals_auctions_status''),',
'           STATUS          = LOOKUPS_MNT.lookup_detail_id_by_code (p_lookup_detail_code => ''declined_request'', p_lookup_code => ''individual_request_status''),',
'           PROGRESS_STATUS = LOOKUPS_MNT.lookup_detail_id_by_code (p_lookup_detail_code => ''decline_auction'', p_lookup_code => ''individual_auction_progress'')',
'     WHERE ID = :P8_INDIVIDUALS_ID;',
'',
'    IF SQL%ROWCOUNT = 0 THEN',
'            RAISE_APPLICATION_ERROR(-20002, '' Server Error'');',
