 p_id=>wwv_flow_imp.id(192935215073116830)
,p_plug_name=>'Request Details'
,p_plug_display_sequence=>40
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select s.ID as ID,',
'       s.TRADE_NAME_AR as TRADE_NAME_AR,',
'       s.TRADE_NAME_EN as TRADE_NAME_EN,',
'       d.APPLICANT_NAME as APP_NAME,',
'       d.APPLICANT_PHONE_NUMBER as APP_PHONE_NUMBER,',
'       d.APPLICANT_EMAIL as APP_EMAIL,',
'       s.OTHER_SELLER_TYPE as OTHER_SELLER_TYPE,',
'       s.SELLER_TYPE_ID as SELLER_TYPE_ID,',
'       s.IDENTITY_NUMBER as SELL_IDENTITY_NUMBER,',
'       s.TAX_NUMBER as TAX_NUMBER,',
'       d.APPLICANT_TYPE_ID as APPLICANT_TYPE_ID,',
'       s.COUNTRY_ID as COUNTRY_ID,',
'       LISTAGG(DISTINCT SELLER_CITIES.CITY_ID, '', '') AS CITY_ID,',
'       LISTAGG(DISTINCT SELLER_CATEGORIES.CATEGORY_ID, '', '') AS CATEGORY_ID,',
'       d.ID AS REQUESTS_DETAILS_ID,',
'       d.PORTABLE_CONFIRMATION as PORTABLE_CONFIRMATION,',
'       d.REALESTATE_CONFIRMATION as REALESTATE_CONFIRMATION',
'  from SELLERS_REQUESTS_DETAILS d,',
'       SELLERS s,',
'       SELLER_CITIES,',
'       SELLER_CATEGORIES',
' where s.ID = d.SELLER_ID (+)',
'       AND s.ID = SELLER_CITIES.SELLER_ID (+)',
'       AND s.ID = SELLER_CATEGORIES.SELLER_ID (+)',
' GROUP BY s.ID, s.TRADE_NAME_AR, s.TRADE_NAME_EN, d.APPLICANT_NAME,',
'          d.APPLICANT_PHONE_NUMBER, d.APPLICANT_EMAIL, s.SELLER_TYPE_ID, s.IDENTITY_NUMBER,',
'          s.TAX_NUMBER, d.APPLICANT_TYPE_ID, s.COUNTRY_ID, OTHER_SELLER_TYPE, d.ID, d.REALESTATE_CONFIRMATION, d.PORTABLE_CONFIRMATION'))
,p_is_editable=>false
,p_plug_source_type=>'NATIVE_FORM'
);
