wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(57445151726923909)
,p_name=>'P9_MANG_IS_ACCOUNT_ADMIN'
,p_item_sequence=>270
,p_item_plug_id=>wwv_flow_imp.id(92552128190263329)
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_mang_is_account_admin NUMBER := 0; ',
'BEGIN ',
'    FOR i IN (SELECT IS_MANAGER, IS_ADMIN FROM EMPLOYEES WHERE SELLER_ID = :P9_ID) LOOP',
'        IF i.IS_MANAGER = 1 AND i.IS_ADMIN = 1 THEN',
'            v_mang_is_account_admin := 1;',
'        ELSIF i.IS_MANAGER = 1 AND i.IS_ADMIN = 0 THEN',
'            v_mang_is_account_admin := 0;',
'        ELSIF i.IS_MANAGER = 0 AND i.IS_ADMIN = 1 THEN',
'            v_mang_is_account_admin := 0;',
'        ELSE',
'            v_mang_is_account_admin := -999;',
'        END IF;',
'    END LOOP;',
'',
'    RETURN v_mang_is_account_admin;',
'END;'))
,p_source_type=>'FUNCTION_BODY'
,p_source_language=>'PLSQL'
,p_display_as=>'NATIVE_HIDDEN'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'value_protected', 'Y')).to_clob
);
