,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_result SELLERS_REQ.function_result;',
'BEGIN',
'',
'    v_result := SELLERS_REQ.CONFIRM_REQUEST ( p_emp_id => :P_EMP_ID, p_seller_id => :P9_ID); ',
