wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(65876406316933518)
,p_process_sequence=>4030
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Approve Request'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_result SELLERS_REQ.function_result;',
'    l_result                    NUMBER;',
'    v_count                     NUMBER;',
'    v_portable_confirmation     NUMBER;',
'    v_realestate_confirmation   NUMBER;',
'    l_message                   VARCHAR2(500);',
'    l_email                     VARCHAR2(500);',
'BEGIN',
'',
'    SELECT COUNT(1) INTO v_count FROM SELLER_categories WHERE SELLER_ID = :P9_ID;',
'    SELECT PORTABLE_CONFIRMATION, REALESTATE_CONFIRMATION INTO v_portable_confirmation, v_realestate_confirmation FROM SELLERS_REQUESTS_DETAILS WHERE SELLER_ID = :P9_ID;',
'    IF  v_count = 1 THEN ',
'',
'        v_result := SELLERS_REQ.activate_seller ( p_seller_id => :P9_ID, p_seller_type => :P9_SELLER_TYPE_ID  );',
'        IF v_result.code <> 1 THEN',
'            RAISE_APPLICATION_ERROR (-20001, v_result.code || '' - '' || v_result.message);',
'        END IF;',
'',
'         -- SEND NOTIFICATION',
'        INSERT INTO SELLER_NOTIFICATIONS ( SELLER_ID, MESSAGE_AR, TYPE_ID )',
'            VALUES ( :P10_SELLER_ID,',
unistr('                     ''\062A\0645 \062A\0623\0643\064A\062F \0642\0628\0648\0644\0643 \0641\064A \0645\0646\0635\0629 \0645\0628\0627\0634\0631!'','),
'                     227 );',
'',
'        IF SQL%Rowcount = 0 THEN',
'            RAISE_APPLICATION_ERROR (-20003, ''Failed to Send Notification record'');',
'        END IF;',
'',
'        -- SEND EMAIL',
'        BEGIN',
'            SELECT EMAIL INTO l_email',
'              FROM EMPLOYEES',
'             WHERE SELLER_ID = :P10_SELLER_ID',
'                   AND IS_ADMIN = 1;',
'        EXCEPTION',
'            WHEN NO_DATA_FOUND THEN',
'                l_email := ''a.awad@mobasher.sa'';',
'        END;',
'',
'        l_result := SYSTEM_CONTROLS.send_email ( ',
'                        p_to       => l_email,',
unistr('                        p_subject  => ''\062A\062D\062F\064A\062B \0628\0627\0644\0637\0644\0628 \0639\0644\0649 \0645\0646\0635\0629 \0645\0628\0627\0634\0631 \0644\0644\0645\0632\0627\062F\0627\062A'','),
unistr('                        p_html     => ''\062A\0645 \062A\0623\0643\064A\062F \0642\0628\0648\0644\0643 \0643\0628\0627\0626\0639 \0641\064A \0645\0646\0635\0629 \0645\0628\0627\0634\0631 \0644\0644\0645\0632\0627\062F\0627\062A!'','),
'                        p_message  => l_message',
'                    );',
'',
'        IF l_result <> 1 THEN',
'            RAISE_APPLICATION_ERROR (-20005, l_message);',
'        END IF;',
'    END IF;--v_count = 1',
'',
'    IF v_count > 1 THEN ',
'        IF v_portable_confirmation = 1 AND v_realestate_confirmation = 1 THEN',
'',
'            v_result := SELLERS_REQ.activate_seller ( p_seller_id => :P9_ID, p_seller_type => :P9_SELLER_TYPE_ID  );',
'',
'            IF v_result.code <> 1 THEN',
'                RAISE_APPLICATION_ERROR (-20001, v_result.code || '' - '' || v_result.message);',
'            END IF;',
'',
'             -- SEND NOTIFICATION',
'            INSERT INTO SELLER_NOTIFICATIONS ( SELLER_ID, MESSAGE_AR, TYPE_ID )',
'                VALUES ( :P10_SELLER_ID,',
unistr('                         ''\062A\0645 \062A\0623\0643\064A\062F \0642\0628\0648\0644\0643 \0641\064A \0645\0646\0635\0629 \0645\0628\0627\0634\0631!'','),
'                         227 );',
'',
'            IF SQL%Rowcount = 0 THEN',
'                RAISE_APPLICATION_ERROR (-20003, ''Failed to Send Notification record'');',
'            END IF;',
'',
'            -- SEND EMAIL',
'            BEGIN',
'                SELECT EMAIL INTO l_email',
'                  FROM EMPLOYEES',
'                 WHERE SELLER_ID = :P10_SELLER_ID',
'                       AND IS_ADMIN = 1;',
'            EXCEPTION',
'                WHEN NO_DATA_FOUND THEN',
'                    l_email := ''a.awad@mobasher.sa'';',
'            END;',
'',
'            l_result := SYSTEM_CONTROLS.send_email ( ',
'                            p_to       => l_email,',
unistr('                            p_subject  => ''\062A\062D\062F\064A\062B \0628\0627\0644\0637\0644\0628 \0639\0644\0649 \0645\0646\0635\0629 \0645\0628\0627\0634\0631 \0644\0644\0645\0632\0627\062F\0627\062A'','),
unistr('                            p_html     => ''\062A\0645 \062A\0623\0643\064A\062F \0642\0628\0648\0644\0643 \0643\0628\0627\0626\0639 \0641\064A \0645\0646\0635\0629 \0645\0628\0627\0634\0631 \0644\0644\0645\0632\0627\062F\0627\062A!'','),
'                            p_message  => l_message',
'                        );',
'',
'            IF l_result <> 1 THEN',
'                RAISE_APPLICATION_ERROR (-20005, l_message);',
'            END IF;',
'        END IF;',
'    END IF; -- v_count > 1',
'',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(92718541114214850)
,p_process_success_message=>'Seller has been approved successfully'
,p_internal_uid=>49590273929683116
