 p_id=>wwv_flow_imp.id(50188574797284364)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'REJECT'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_result  NUMBER;',
'    l_email   VARCHAR2(255);',
'    l_message VARCHAR2(500);',
'    v_result  SELLERS_REQ.function_result;',
'BEGIN',
'    v_result := SELLERS_REQ.reject_seller ( p_emp_id        => :P_EMP_ID,',
'                                            p_seller_id     => :P10_SELLER_ID,',
'                                            p_reject_reason => :P10_REASON,',
'                                            p_seller_type   => :P10_SELLER_TYPE );',
'',
'    IF v_result.code <> 1 THEN',
'        RAISE_APPLICATION_ERROR (-20001, v_result.code || '' - '' || v_result.message);',
'    END IF;',
'',
'    -- SEND EMAIL',
'    BEGIN',
'        -- SELECT DEFAULT_EMAIL INTO l_email',
'        --   FROM SELLERS',
'        --  WHERE ID = :P10_SELLER_ID;',
'        SELECT EMAIL INTO l_email',
'          FROM EMPLOYEES',
'         WHERE SELLER_ID = :P10_SELLER_ID',
'               AND IS_ADMIN = 1;',
'    EXCEPTION',
'        WHEN NO_DATA_FOUND THEN',
'            l_email := ''a.awad@mobasher.sa'';',
'    END;',
'',
'    l_result := SYSTEM_CONTROLS.send_email (',
'                    p_to       => l_email,',
unistr('                    p_subject  => '' \0625\0634\0639\0627\0631 \0628\0631\0641\0636 \0637\0644\0628\0643'','),
'                    p_html     => :P10_REASON,',
'                    p_message  => l_message',
'                );',
'',
'    IF l_result <> 1 THEN',
'        RAISE_APPLICATION_ERROR (-20003, l_message);',
'    END IF;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(50179979675284357)
,p_process_success_message=>'Seller has been rejected successfully'
,p_internal_uid=>33902442410033962
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(50188935507284365)
,p_process_sequence=>30
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Edit Request'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_result    NUMBER;',
'    l_message   VARCHAR2(500);',
'    l_email     VARCHAR2(500);',
'BEGIN',
'    l_result := APP_OPERATIONS.CREATE_NOTES ( p_emp_id         => :P_EMP_ID,',
'                                              p_object_id      => :P10_SELLER_ID,',
'                                              p_operation_type => LOOKUPS_MNT.lookup_detail_id_by_code(''request_edit_mobasher'', ''operation_type''),',
'                                              p_note           => :P10_NOTES,',
'                                              p_message        => l_message',
'                );',
'',
'    IF l_result <> 1 THEN',
'        RAISE_APPLICATION_ERROR (-20001, l_result || '' - '' || l_message);',
'    END IF;',
'',
'    UPDATE SELLERS_REQUESTS_DETAILS',
'       SET IS_EDITABLE = 1',
'     WHERE SELLER_ID = :P10_SELLER_ID;',
'',
'    IF SQL%Rowcount = 0 THEN',
'        RAISE_APPLICATION_ERROR (-20002, ''Failed to send edits record'');',
'    END IF;',
'',
'    -- SEND NOTIFICATION',
'    INSERT INTO SELLER_NOTIFICATIONS ( SELLER_ID, MESSAGE_AR, TYPE_ID )',
'        VALUES ( :P10_SELLER_ID, :P10_NOTES, 227 );',
'',
'    IF SQL%Rowcount = 0 THEN',
'        RAISE_APPLICATION_ERROR (-20003, ''Failed to Send Notification record'');',
'    END IF;',
'',
'    -- SEND EMAIL',
'    BEGIN',
'        SELECT EMAIL INTO l_email',
'          FROM EMPLOYEES',
'         WHERE SELLER_ID = :P10_SELLER_ID',
'               AND IS_ADMIN = 1;',
'    EXCEPTION',
'        WHEN NO_DATA_FOUND THEN',
'            l_email := ''a.awad@mobasher.sa'';',
'    END;',
'',
'    l_result := SYSTEM_CONTROLS.send_email ( ',
'                    p_to       => l_email,',
unistr('                    p_subject  => '' \0625\0634\0639\0627\0631 \0628\0637\0644\0628 \062A\0639\062F\064A\0644\0627\062A \0639\0644\0649 \0637\0644\0628\0643'','),
'                    p_html     => :P10_NOTES,',
'                    p_message  => l_message',
'                );',
'',
'    IF l_result <> 1 THEN',
'        RAISE_APPLICATION_ERROR (-20005, l_message);',
'    END IF;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(50181120596284358)
,p_process_success_message=>'Your edits have been sent successfully'
,p_internal_uid=>33902803120033963
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(50185818580284362)
,p_process_sequence=>60
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Upload Contract Real estate'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_file_names        APEX_T_VARCHAR2;',
'    l_file              APEX_APPLICATION_TEMP_FILES%ROWTYPE;',
'    l_file_name         VARCHAR2(255);',
'    l_request_url	    VARCHAR2(32767);',
'    l_result	        CLOB;',
'    l_request_filename	VARCHAR2(500);',
'    l_inner_folder  	VARCHAR2(500);',
'BEGIN',
'    l_file_names := apex_string.SPLIT (',
'                        p_str => :P10_REAL_ESTATE_CONTRACT,',
'                        p_sep => '':'' );',
'',
'    IF l_file_names.count = 0 THEN',
unistr('        RAISE_APPLICATION_ERROR(-20001, ''\064A\062C\0628 \0639\0644\064A\0643 \0625\0631\0641\0627\0642 \0627\0644\0639\0642\062F \0623\0648\0644\0627'');'),
'    END IF;',
'',
'    SELECT *',
'      INTO l_file',
'      FROM APEX_APPLICATION_TEMP_FILES',
'     WHERE NAME = :P10_REAL_ESTATE_CONTRACT;',
'',
'    l_file_name := TO_CHAR(get_current_date, ''YY'') ',
'                        || DBMS_RANDOM.STRING(''x'', 8)',
'                        || SYSTEM_CONTROLS.file_extension_by_mimetype(p_mimetype => l_file.MIME_TYPE);',
'',
'    l_request_url := :G_OCI_BASE_URL||''/b/seller_signup/o/''||l_file_name;',
'    ',
'    l_result := APEX_WEB_SERVICE.make_rest_request (',
'                    p_url                  => l_request_url,',
'                    p_http_method          => ''PUT'',',
'                    p_body_blob            => l_file.BLOB_CONTENT,',
'                    p_credential_static_id => ''OCI_AUTH''',
'                );',
'',
'    IF APEX_WEB_SERVICE.g_status_code NOT IN ( 200, 201, 202, 203, 204, 205, 206, 207, 226 ) THEN',
'        SYSTEM_CONTROLS.ERROR_LOGS ( p_error_type    => ''SYSTEM_ERROR'',',
'                                         p_process_name  => ''OCI_OS.put_object_P10 - App: '' || :APP_ID,',
'                                         p_error_code    => -2,',
'                                         p_error_message => SUBSTR(l_result, 1, 4000),',
'                                         p_logger_name   => :APP_USER',
'                                    );',
'        RAISE_APPLICATION_ERROR(-20004, ''Error with uploading Data!'');',
'    END IF;',
'    ',
'    :P10_REAL_ESTATE_CONTRACT_URL := l_request_url;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(50172548163284351)
,p_internal_uid=>33899686193033960
);
