,p_component_template_options=>'#DEFAULT#:t-AVPList--rightAligned'
,p_new_grid_row=>false
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT -- ALL NEEDED FOR PRODUCT REGION',
'       --FROM PRODUCT TABLE ',
'       p.ID AS PRODUCT_ID,',
'       p.CITY_ID AS CITY,',
'       p.CATEGORY_ID AS PRODUCT_CATEGORY,',
'    --    p.MAIN_IMAGE_URL,',
'       CASE ',
'        WHEN p.MAIN_IMAGE_URL IS NOT NULL THEN',
'        ''<img src="''|| p.MAIN_IMAGE_URL ||''" alt="Logo Image" class="logo-image" style="width:25px;height:25px;" />''',
'        ELSE ''''',
'        END AS MAIN_IMAGE,',
'       --real estate',
'       r.ID AS REAL_ESTATE_ID,',
'       r.NEIGHBOURHOODS_ID AS NEIGHBOURHOODS,',
'       r.STREET_NAME_AR AS STREET_NAME,',
'       r.USAGE_ID AS USAGE,',
'       r.FACADE_ID AS FACADE,',
'       r.PROPERTY_TYPE_ID AS BUILDING_TYPE,',
'       r.SPACE,',
'       -- FROM THE REQUEST',
'       i.ID AS REQUEST_ID,',
'       i.IS_FULLY_OWNED,',
'       i.OWNED_PERCENTAGE,',
'       i.IS_INSTRUMENT_VALID,',
'       i.INSTRUMENT_NUMBER,',
'       i.MORTGAGE_NOTES,',
'       i.OBLIGATIONS_NOTES,',
'       i.AFFECTED_INFO_NOTES,',
'       i.IS_PROPERTY_RATED,',
'       i.HOW_RATE_PROPERTY,',
'       i.IS_FULLY_SELL,',
'       NULL AS Attachments,',
'       NULL AS PROPERTY_DIMENSIONS,',
'       NULL AS PROPERTY_SERVICES,',
unistr('       DECODE(NVL(:P_LANG, ''ar''), ''en'', ''\062A\062D\0645\064A\0644 \0627\0644\0645\0632\064A\062F '',''Load More '' ) AS LOAD_MORE,'),
unistr('       DECODE(NVL(:P_LANG, ''ar''), ''en'', ''\062A\062D\0645\064A\0644 \0623\0642\0644 '',''Load Less '' ) AS LOAD_LESS'),
' FROM PRODUCTS p,',
'      REAL_STATE_DETAILS r,',
'      INDIVIDUAL_REALESTATE_REQUESTS i',
'WHERE i.ID = :P12_REQUEST_ID',
'  AND p.ID = r.PRODUCT_ID',
'  AND p.ID = i.PRODUCT_ID'))
,p_read_only_when_type=>'ALWAYS'
,p_ajax_enabled=>'Y'
,p_ajax_items_to_submit=>'P12_REQUEST_ID'
,p_lazy_loading=>false
,p_query_row_template=>wwv_flow_imp.id(28069420468807415)
,p_query_num_rows=>15
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_query_row_count_max=>5
,p_csv_output=>'N'
,p_prn_output=>'N'
,p_sort_null=>'F'
,p_plug_query_strip_html=>'N'
);
