wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(38147587271059624)
,p_plug_name=>'Images'
,p_parent_plug_id=>wwv_flow_imp.id(79257417331703732)
,p_region_template_options=>'#DEFAULT#:t-Region--noPadding:t-Region--removeHeader js-removeLandmark:t-Region--noBorder:t-Region--scrollBody'
,p_plug_template=>wwv_flow_imp.id(86296507817821564)
,p_plug_display_sequence=>40
,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_result clob;',
'    l_img APEX_T_VARCHAR2;',
'    l_single_elemant APEX_T_VARCHAR2;',
'    items VARCHAR2(5000);',
'    total integer;',
'BEGIN',
'    l_result := l_result ||''<div class="container-slider">',
'                               <div class="slides">'';',
'    SELECT IMAGES_URLS',
'      into items',
'      FROM  PRODUCTS',
'     WHERE ID = :P12_PRODUCT_ID;',
'        l_single_elemant := apex_string.SPLIT (',
'                            p_str => items,',
'                            p_sep => '','' );',
'                            ',
'    :P12_IMGS_LENGTH := l_single_elemant.COUNT;',
'    ',
'     FOR i in 1 ..l_single_elemant.COUNT LOOP',
'',
'        l_result := l_result || ''<img src="''|| l_single_elemant(i) ||''" alt="">'';',
'    END LOOP;                     ',
'    l_result := l_result ||   ''</div>',
'                               <span class="btn-slide prev">',
'                                  <img src="https://imgur.com/SUyRJqI.png" alt="prevBtn" />',
'                               </span>',
'                               <span class="btn-slide next">',
'                                   <img src=" https://imgur.com/M6rDsRR.png" alt="nextBtn" />',
'                               </span>',
'                               <div class="container-dots">',
'',
'                               </div>',
'                            </div>'';',
'',
'    RETURN l_result;',
'END;'))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_DYNAMIC_CONTENT'
,p_ajax_items_to_submit=>'P12_PRODUCT_ID'
);
