wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(66226882488778152)
,p_name=>'Product Info'
,p_parent_plug_id=>wwv_flow_imp.id(66225799159778141)
,p_template=>wwv_flow_imp.id(86296507817821564)
,p_display_sequence=>30
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_component_template_options=>'#DEFAULT#:t-AVPList--rightAligned'
,p_new_grid_row=>false
,p_display_point=>'SUB_REGIONS'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- ALL NEEDED FOR PRODUCT REGION',
'--FROM PRODUCT TABLE ',
'SELECT p.ID AS PORTABLE_PRODUCT_ID,',
'       p.CITY_ID AS CITY,',
'       p.CATEGORY_ID AS CATEGORY,',
'       ',
'      CASE ',
'        WHEN p.MAIN_IMAGE_URL IS NOT NULL THEN',
'        ''<img src="''|| p.MAIN_IMAGE_URL ||''" alt="Logo Image" class="logo-image" style="width:25px;height:25px;" />''',
'        ELSE ''''',
'        END AS MAIN_IMAGE,',
'       -- car details ',
'       c.ID AS PORTABLE_DETAILS_ID,',
'       c.PRODUCT_ID AS PORTABLE_DETAILS_PRODUCT_ID,',
'       c.VEHICLE_MAKE_ID AS VEHICLE_MAKE,',
'       c.VEHICLE_MODEL_ID AS VEHICLE_MODEL,',
'       c.YEAR,',
'       c.CHASSIS_NUMBER ,',
'       c.TRANSMISSION_ID AS TRANSMISSION,',
'       c.VEHICLE_EXTERNAL_COLOR_ID AS VEHICLE_EXTERNAL_COLOR,',
'       c.VEHICLE_INNER_COLOR_ID AS VEHICLE_INNER_COLOR,',
'       c.FUEL_TYPE_ID AS FUEL_TYPE,',
'       c.ODO_METER,',
'       c.IS_THERE_DOCUMENT,',
'       c.IS_THERE_INSPECTION,',
'       c.IS_DROWNED AS HAS_VEHICLE_DROWNNED,',
'       c.IS_BURNED AS HAS_VEHICLE_BURNED,',
'       c.IS_ACCIDENT AS HAS_VEHICLE_GOT_ACCIDENT,',
'       -- request table',
'       i.ID AS INDIVIDUAL_PORTABLE_REQUEST_ID,',
'       i.EXTRA_NOTES AS INDIVIDUAL_PORTABLE_NOTES,',
'       NULL AS ATTACHMENTS,',
unistr('       DECODE(NVL(:P_LANG, ''ar''), ''en'', ''\062A\062D\0645\064A\0644 \0627\0644\0645\0632\064A\062F: '',''Load More: '' ) AS LOAD_MORE,'),
unistr('       DECODE(NVL(:P_LANG, ''ar''), ''en'', ''\062A\062D\0645\064A\0644 \0623\0642\0644: '',''Load Less: '' ) AS LOAD_LESS'),
'FROM PRODUCTS p,',
'     CAR_DETAILS c,',
'     INDIVIDUAL_PORTABLE_REQUESTS i',
'WHERE i.ID = :P13_REQUEST_ID ',
'  AND p.ID = c.PRODUCT_ID',
'  AND p.ID = i.PRODUCT_ID',
'  '))
,p_read_only_when_type=>'ALWAYS'
,p_ajax_items_to_submit=>'P13_REQUEST_ID'
,p_lazy_loading=>false
,p_query_row_template=>wwv_flow_imp.id(28069420468807415)
,p_query_num_rows=>15
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_query_row_count_max=>5
,p_csv_output=>'N'
,p_prn_output=>'N'
,p_sort_null=>'L'
,p_plug_query_strip_html=>'N'
);
