,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT pa.ID,',
'       lpad(''T'' ||pa.PRODUCT_ID , 5) AS CODE,',
'       pa.PRODUCT_ID,',
'       pa.START_DATE,',
'       p.NAME_AR,',
