'       pa.END_DATE,',
'       pa.INSURANCE,',
'       pa.START_PRICE,',
'       pa.EVERY_CLICK,',
'       pa.ALLOW_SELL_PRICE,',
'       pa.TERMS_AR',
'  FROM PRODUCT_IN_TIMED_AUCTION pa, PRODUCTS p',
' WHERE pa.AUCTION_CONTAINER_ID = :P15_AUCTION_ID',
