,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT -- ALL NEEDED FOR PRODUCT REGION',
'       --FROM PRODUCT TABLE ',
'       p.ID AS PRODUCT_ID,',
'       p.CITY_ID AS CITY,',
'       p.CATEGORY_ID AS CATEGORY,',
'    --    p.MAIN_IMAGE_URL AS PORTABLE_REQUESTS_MAIN_IMAGE_URL,',
'        ''<img src="''|| p.MAIN_IMAGE_URL ||''" alt="Logo Image" class="logo-image" style="width:25px;height:25px;" />''AS MAIN_IMAGE,',
'       -- car details ',
'       c.ID AS CAR_DETAILS_ID,',
'       c.PRODUCT_ID AS CAR_DETAILS_PRODUCT_ID,',
'       c.VEHICLE_MAKE_ID AS VEHICLE_MAKE,',
'       c.VEHICLE_MODEL_ID AS VEHICLE_MODEL,',
'       c.YEAR,',
'       c.CHASSIS_NUMBER,',
'       c.TRANSMISSION_ID AS TRANSMISSION,',
'       c.VEHICLE_EXTERNAL_COLOR_ID AS VEHICLE_EXTERNAL_COLOR,',
'       c.VEHICLE_INNER_COLOR_ID AS VEHICLE_INNER_COLOR,',
'       c.FUEL_TYPE_ID,',
'       c.ODO_METER,',
'       c.IS_THERE_DOCUMENT,',
'       c.IS_THERE_INSPECTION,',
'       --request table',
'       i.ID AS PORTABLE_REQUEST_ID,',
'       i.PRODUCT_ID AS PORTABLE_REQUEST_PEODUCT_ID,',
'       i.BUYER_ID AS ID,',
'       i.BUYER_NAME AS NAME ,',
'       i.BUYER_PHONE AS PHONE,',
'       i.BUYER_NID_TYPE AS NATIONAL_TYPE,',
'       i.BUYER_NATIONAL_ID AS NATIONAL_ID,',
'       i.MINIMUM_SELL_PRICE AS MINIMUM_SELL_PRICE,',
'       i.REQUEST_STATUS AS REQUEST_STATUS,',
'       i.STATUS AS APPLICATION_STATUS,',
'       i.CREATED_DATE,',
'       NULL AS ACTIONS',
'FROM PRODUCTS p,',
'     CAR_DETAILS c,',
'     INDIVIDUAL_PORTABLE_REQUESTS i',
'WHERE p.ID = c.PRODUCT_ID(+)',
'  AND p.ID = i.PRODUCT_ID',
'  AND (i.REQUEST_STATUS = :P26_STATUS_ID OR :P26_STATUS_ID IS NULL)',
'  AND (i.PRODUCT_ID in (SELECT ID FROM PRODUCTS WHERE CATEGORY_ID IN (EMP_CATEGORY_BY_ID (p_employee_id  => :P_EMP_ID))) OR IS_EMP_ADMIN_BY_ID (p_employee_id => :P_EMP_ID) = 1)',
'  ORDER BY i.CREATED_DATE DESC'))
,p_plug_source_type=>'NATIVE_IR'
