,p_plug_name=>'Auction Status '
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(86236996114821533)
,p_plug_display_sequence=>120
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT COUNT(ID) AS COUNT,',
'        LOOKUPS_MNT.lookup_detail_name_by_id (  ',
'            p_lookup_detail_id  => REQUEST_STATUS,  ',
'            p_lang              => :P_LANG',
'        ) AS REQUEST_STATUS,',
'        REQUEST_STATUS AS STATUS_ID',
'   FROM INDIVIDUAL_PORTABLE_REQUESTS',
'  WHERE LOOKUPS_MNT.lookup_detail_code_by_id (p_lookup_detail_id => REQUEST_STATUS) IN (''wokring_on'', ''done'', ''archive'')',
'   AND PRODUCT_ID IS NOT NULL',
'   AND (PRODUCT_ID in (SELECT ID FROM PRODUCTS WHERE CATEGORY_ID IN (EMP_CATEGORY_BY_ID (p_employee_id  => :P_EMP_ID))) OR IS_EMP_ADMIN_BY_ID (p_employee_id => :P_EMP_ID) = 1)',
'  GROUP BY REQUEST_STATUS;',
'',
'  ',
'',
''))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_CARDS'
,p_ajax_items_to_submit=>'P26_STATUS_ID, P_EMP_ID'
,p_plug_query_num_rows_type=>'SCROLL'
,p_show_total_row_count=>false
);
