wwv_flow_imp_page.create_page(
 p_id=>27
,p_name=>'Individual Real Estates Auctions Management'
,p_alias=>'INDIVIDUAL-REAL-ESTATES-AUCTIONS-MANAGEMENT'
,p_step_title=>'Individual Real Estates Auctions Management'
,p_autocomplete_on_off=>'OFF'
,p_javascript_code_onload=>wwv_flow_string.join(wwv_flow_t_varchar2(
'let menu$ = $("<div id=''realEstateEditMenu''></div>");',
'let details, edit;',
'',
'if ($v(''P27_LANG'') == ''en'') {',
'    details = "View Details";',
'    edit = "Edit Status";',
'} else {',
unistr('    details = ''\0639\0631\0636 \0627\0644\062A\0641\0627\0635\064A\0644'';'),
unistr('    edit = "\062A\063A\064A\064A\0631 \062D\0627\0644\0629 \0627\0644\0637\0644\0628";'),
'}',
'$("body").append(menu$);',
'menu$.menu({',
'    iconType: "fa",',
'    items: [',
'        {',
'            type: "action",',
'            labelKey: details,',
'            icon: "fa-info-circle-o",',
'        },',
'        {',
'            type: "action",',
'            labelKey: edit,',
'            icon: "fa-pencil-square-o",',
'        }',
'    ]',
'});',
''))
,p_inline_css=>wwv_flow_string.join(wwv_flow_t_varchar2(
'.a-CardView-item {',
'    cursor: pointer;',
'    align: center;',
'}',
'.card {',
' width: 90px;',
' height: auto;',
' border-radius: 30px;',
' text-align: center',
'}'))
,p_page_template_options=>'#DEFAULT#'
,p_protection_level=>'C'
,p_page_component_map=>'23'
);
