wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(78824347807039190)
,p_plug_name=>'Individuals auction'
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(86286645774821557)
,p_plug_display_sequence=>90
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT r.ID AS REAL_STATE_ID,',
'       r.NEIGHBOURHOODS_ID AS NEIGHBOURHOODS,',
'       r.STREET_NAME_AR AS STREET_NAME,',
'       r.INSTRUMENT_NO AS INSTRUMENT,',
'       r.USAGE_ID AS USAGE,',
'       r.FACADE_ID AS FACADE,',
'       r.PROPERTY_TYPE_ID AS PROPERTY_TYPE,',
'       r.SPACE,',
'       --PRODUCTS',
'       p.ID AS PRODUCT_ID,',
'       p.CITY_ID AS CITY,',
'       p.CATEGORY_ID AS CATEGORY,',
'       p.NAME_AR AS NAME,',
'       CASE ',
'        WHEN p.MAIN_IMAGE_URL IS NOT NULL THEN',
'        ''<img src="''|| p.MAIN_IMAGE_URL ||''" alt="Logo Image" class="logo-image" style="width:25px;height:25px;" />''',
'        ELSE ''''',
'        END AS MAIN_IMAGE,',
'       -- REQUEST',
'       i.ID AS  INDIVIUAL_REQUEST_ID,',
'       i.BUYER_ID AS BUYER_ID_, ',
'       i.BUYER_NAME, ',
'       i.BUYER_PHONE AS PHONE, ',
'       i.BUYER_NATIONAL_ID AS NATIONAL_ID, ',
'       i.IS_INSTRUMENT_VALID, ',
'    --    i.IS_ACCEPT_TERMS_AND_CONDITIONS, ',
'       i.AUTHORIZATION_NUMBER, ',
'       i.AUTHORIZATION_DATE, ',
'       i.AUTHORIZATION_ADDRESS, ',
'       ''<img src="''|| i.AUTHORIZATION_URL ||''" alt="Logo Image" class="logo-image" style="width:25px;height:25px;" />'' AS AUTHORIZATION,',
'       i.VAL_LICENSE_NUMBER, ',
'       i.LICENSE_TYPE, ',
'       i.LICENSE_EXPIRY_DATE, ',
'       ''<img src="''|| i.VAL_LICENSE_URL ||''" alt="Logo Image" class="logo-image" style="width:25px;height:25px;" />'' AS VAL_LICENSE,',
'    --    i.VAL_LICENSE_URL, ',
'       ''<img src="''|| i.MEDIATION_CONTRACT_URL ||''" alt="Logo Image" class="logo-image" style="width:25px;height:25px;" />'' AS MEDIATION_CONTRACT,',
'    --    i.MEDIATION_CONTRACT_URL, ',
'       i.IS_PROPERTY_RATED, ',
'       ''<img src="''|| i.PROPERTY_RATED_URL ||''" alt="Logo Image" class="logo-image" style="width:25px;height:25px;" />'' AS PROPERTY_RATED,',
'    --    i.PROPERTY_RATED_URL, ',
'       i.IS_FULLY_OWNED, ',
'       i.OWNED_PERCENTAGE, ',
'       i.IS_FULLY_SELL, ',
'       i.SELL_PERCENTAGE, ',
'       ''<img src="''|| i.SELL_AUTHORIZATION_URL ||''" alt="Logo Image" class="logo-image" style="width:25px;height:25px;" />'' AS SELL_AUTHORIZATION,',
'    --    i.SELL_AUTHORIZATION_URL, ',
'       i.REQUESTER_AS,',
'       i.REQUEST_STATUS,',
'       i.STATUS,',
'       i.PROGRESS_STATUS,',
'       i.CREATED_DATE,',
'       NULL AS ACTIONS',
'FROM REAL_STATE_DETAILS r, INDIVIDUAL_REALESTATE_REQUESTS i, PRODUCTS p',
'WHERE p.ID = r.PRODUCT_ID',
'  AND p.ID = i.PRODUCT_ID',
'  AND ( i.REQUEST_STATUS = :P27_STATUS_ID OR :P27_STATUS_ID IS NULL )',
'  AND (i.PRODUCT_ID in (SELECT ID FROM PRODUCTS WHERE CATEGORY_ID IN (EMP_CATEGORY_BY_ID (p_employee_id  => :P_EMP_ID))) OR IS_EMP_ADMIN_BY_ID (p_employee_id => :P_EMP_ID) = 1)',
' ORDER BY i.CREATED_DATE asc'))
,p_plug_source_type=>'NATIVE_IR'
,p_ajax_items_to_submit=>'P27_STATUS_ID,P_EMP_ID'
,p_prn_content_disposition=>'ATTACHMENT'
