,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Approve Request'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    IF :P32_TYPE = ''editBankAccount'' THEN ',
'        UPDATE BUYER_BANK_ACCOUNT_REQUESTS',
'           SET STATUS = LOOKUPS_MNT.lookup_detail_id_by_code(''approved'', ''request_status'')',
'         WHERE ID = :P32_BANK_ID;',
'        IF SQL%ROWCOUNT = 0 THEN ',
'            RAISE_APPLICATION_ERROR (-20001, SYSTEM_CONTROLS.get_translation(p_code => ''server_error'', p_lang => :P_LANG));',
'        END IF;',
'    END IF;',
'',
'    IF :P32_TYPE = ''editAddess'' THEN',
'        UPDATE BUYER_ADDRESS_REQUESTS',
'           SET STATUS = LOOKUPS_MNT.lookup_detail_id_by_code(''approved'', ''request_status'')',
'         WHERE ID = :P32_ADDRESS_ID;',
'        IF SQL%ROWCOUNT = 0 THEN ',
'            RAISE_APPLICATION_ERROR (-20002, SYSTEM_CONTROLS.get_translation(p_code => ''server_error'', p_lang => :P_LANG));',
'        END IF;',
'    END IF;',
'',
'    IF :P32_TYPE = ''deleteAccount'' THEN',
'        UPDATE BUYER_DELETE_ACCOUNT_REQUESTS',
'           SET STATUS = LOOKUPS_MNT.lookup_detail_id_by_code(''approved'', ''request_status'')',
'         WHERE ID = :P32_DELETE_ID;',
'        IF SQL%ROWCOUNT = 0 THEN ',
'            RAISE_APPLICATION_ERROR (-20003, SYSTEM_CONTROLS.get_translation(p_code => ''server_error'', p_lang => :P_LANG));',
'        END IF;',
'    END IF;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(30456648580228019)
,p_process_success_message=>'The request has been approved successfully'
,p_internal_uid=>14395681901588230
);
