'            RAISE_APPLICATION_ERROR (-20001, SYSTEM_CONTROLS.get_translation(p_code => ''missing_data'', p_lang => :P_LANG));',
'        END IF;',
'        UPDATE BUYER_ADDRESS_REQUESTS',
'           SET STATUS = LOOKUPS_MNT.lookup_detail_id_by_code(''rejected'', ''request_status''),',
'               REJECT_REASON = :P32_REJECT_REASON',
'         WHERE ID = :P32_ADDRESS_ID;',
'        IF SQL%ROWCOUNT = 0 THEN ',
'            RAISE_APPLICATION_ERROR (-20002, SYSTEM_CONTROLS.get_translation(p_code => ''server_error'', p_lang => :P_LANG));',
'        END IF;',
'    END IF;',
'',
'    IF :P32_TYPE = ''deleteAccount'' THEN',
'        IF :P32_REJECT_REASON IS NULL THEN',
'            RAISE_APPLICATION_ERROR (-20001, SYSTEM_CONTROLS.get_translation(p_code => ''missing_data'', p_lang => :P_LANG));',
'        END IF;',
'        UPDATE BUYER_DELETE_ACCOUNT_REQUESTS',
'           SET STATUS = LOOKUPS_MNT.lookup_detail_id_by_code(''rejected'', ''request_status''),',
'               REJECT_REASON = :P32_REJECT_REASON',
'         WHERE ID = :P32_DELETE_ID;',
'        IF SQL%ROWCOUNT = 0 THEN ',
'            RAISE_APPLICATION_ERROR (-20003, SYSTEM_CONTROLS.get_translation(p_code => ''server_error'', p_lang => :P_LANG));',
'        END IF;',
'    END IF;',
'END;'))
