wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(31320902844103732)
,p_plug_name=>'Lost Auctions'
,p_parent_plug_id=>wwv_flow_imp.id(30983775290234733)
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(86288806066821560)
,p_plug_display_sequence=>30
,p_plug_display_point=>'SUB_REGIONS'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select --AUCTINO',
'       a.ID AS AUCTION_ID,',
'       a.AUCTION_TYPE_ID,',
'       a.AUCTION_OWNER_ID,',
'       a.INSURANCE_TYPE_ID,',
'       a.NAME_AR AS AUCTION_NAME,',
'       a.BROCHURE_URL,',
'       -- PROD TIMED',
'       pa.ID AS PROD_TIMED_ID,',
'       pa.PRODUCT_ID,',
'       pa.AUCTION_CONTAINER_ID, --AUCTION',
'       pa.START_DATE,',
'       pa.END_DATE,',
'       pa.INSURANCE,',
'       pa.START_PRICE,',
'       pa.IS_ENDED,',
'       pa.LAST_BID,',
'       pa.IS_CREATE_EDAAT_INVOICE AS IS_EDAAT_INVOICE,',
'       pa.IS_CREATE_NAFITH_INVOICE AS IS_NAFITH_INVOICE,',
'       --BUYER TIMED',
'       ba.ID AS BUYER_TIMED_ID,',
'       ba.BUYER_ID,',
'       ba.TIMED_AUCTION_ID, -- prod timed',
'       ba.PARTICIPANT_AS_ID,',
'       ba.IS_INSURANCE_PAID,',
'       ba.IS_INSURANCE_DELIVERED_REFUNDED AS HAS_INSURANCE_REFUNDED,',
'       ba.REFUNDED_DATE,',
'       --PRODUCT',
'       p.ID AS PROD_ID,',
'       p.SELLER_ID AS SELLER_NAME,',
'       p.CITY_ID,',
'       p.CATEGORY_ID,',
'       p.SUB_CATEGORY_ID,',
'       p.NAME_AR AS PRODUCT_NAME',
'  from AUCTIONS a,',
'       PRODUCT_IN_TIMED_AUCTION pa,',
'       BUYER_IN_TIMED_AUCTION ba,',
'       PRODUCTS p',
' WHERE a.ID = pa.AUCTION_CONTAINER_ID',
'   AND pa.ID = ba.TIMED_AUCTION_ID',
'   AND pa.ID = ba.TIMED_AUCTION_ID',
'   AND p.ID = pa.PRODUCT_ID',
'   AND ba.BUYER_ID = :P35_BUYER_ID',
'   AND pa.IS_ENDED = 1',
'   AND ba.IS_WINNER = 0',
'   AND ba.IS_CURRENT_AUCTION = 0'))
,p_plug_source_type=>'NATIVE_IR'
,p_ajax_items_to_submit=>'P35_BUYER_ID'
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_units=>'INCHES'
