 p_id=>wwv_flow_imp.id(30984344935234739)
,p_plug_name=>'Refund Edaat Invoices'
,p_parent_plug_id=>wwv_flow_imp.id(32003154701315426)
,p_region_template_options=>'#DEFAULT#:t-Region--noBorder:t-Region--scrollBody'
,p_plug_template=>wwv_flow_imp.id(86296507817821564)
,p_plug_display_sequence=>10
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT bi.ID,',
'       bi.BUYER_ID,',
'       bi.INVOICE_NO,',
'       bi.TOTAL_PRICE AS INVOICE_PRICE,',
'       bi.INSURANCE_PRICE,',
'       bi.EDAAT_STATUS_ID,',
'       bi.REFUND_STATUS_ID,',
'       bi.REFUND_PRICE,',
'       bi.REFUNDED_DATE,',
'       CASE',
'        WHEN bi.REFUND_INVOICE_URL IS NOT NULL THEN',
'            ''<span class="fa fa-file-o" aria-hidden="true"></span>''',
'        ELSE ''''',
'       END AS REFUND_INVOICE_URL_CLASS,',
'       bi.REFUND_INVOICE_URL,',
'       ba.ID AS BUYER_TIMED_ID,',
'       ba.BUYER_ID AS BUYER_ID_TIMED_ID',
'  FROM BUYER_EDAAT_INSURANCE bi,',
'         BUYER_IN_TIMED_AUCTION ba',
' WHERE ba.BUYER_ID = bi.BUYER_ID',
'   AND bi.BUYER_ID = :P35_BUYER_ID',
'   AND bi.REFUND_STATUS_ID IN (LOOKUPS_MNT.lookup_detail_id_by_code (p_lookup_detail_code => ''refund_request'', p_lookup_code => ''refund_status''),',
'                               LOOKUPS_MNT.lookup_detail_id_by_code (p_lookup_detail_code => ''not_refund'', p_lookup_code => ''refund_status''), null)',
'   AND ba.IS_WINNER = 0',
'   AND ba.IS_CURRENT_AUCTION = 0'))
,p_plug_source_type=>'NATIVE_IR'
,p_ajax_items_to_submit=>'P35_BUYER_ID'
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
,p_prn_width=>11
,p_prn_height=>8.5
