,p_plug_display_sequence=>40
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT SEQ_ID - 1 AS SEQUENCE,',
'       C001 AS PRODUCT_DEPENDENCY,',
'       C003 AS CITY,',
'       C004 AS CATEGORY,',
'       C005 AS SUB_CATEGORY,',
'       C006 AS MAKE,',
'       C007 AS MODEL,',
'       C008 AS CLASS,',
'       C009 AS CHASSIS_NUMBER,',
'       C010 AS PLATE_NUMBER,',
'       C011 AS COLOR,',
'       C012 AS WALKWAY,',
'       C013 AS YEAR,',
'       C014 AS FUEL_TYPE,',
'       C015 AS LOAD,',
'       C016 AS SERIAL_NUMBER,',
'    --    C017 AS STATUS,',
'       DECODE(C017, 1, ''TRUE'', 0, ''FALSE'') AS IS_DRAWED,',
'       DECODE(C018, 1, ''TRUE'', 0, ''FALSE'') AS IS_BURNED,',
'       DECODE(C019, 1, ''TRUE'', 0, ''FALSE'') AS IS_ACCIDENT,',
'       C020 AS ISTEMARA_EXPIRATION,',
'       C021 AS PERIODIC_INSPECTION,',
'       C022 AS PREVIEW_TIMES,',
'       C023 AS DESCRIPTION,',
'       C024 AS ADDRESS,',
'       C025 AS MAP_URL,',
'       C026 AS IMAGES_URS,',
'       C027 AS MAIN_IMAGE_URL,',
'       CASE',
'        WHEN C028 IS NOT NULL THEN',
'            ''<span aria-hidden="true" class="t-Icon fa fa-check" style="color:#026e63;"></span>''',
'        ELSE ''''',
'        END AS IS_IMAGES_URLS,',
'       CASE',
'        WHEN C029 IS NOT NULL THEN',
'            ''<span aria-hidden="true" class="t-Icon fa fa-check" style="color:#026e63;"></span>''',
'        ELSE ''''',
'        END AS IS_MAIN_IMAGE_URL',
'  FROM APEX_COLLECTIONS',
' WHERE COLLECTION_NAME = ''ASSIGNED''',
'   AND SEQ_ID > 1',
' ORDER BY SEQ_ID;'))
,p_plug_source_type=>'NATIVE_IR'
,p_plug_display_condition_type=>'EXISTS'
,p_plug_display_when_condition=>'SELECT 1 FROM APEX_COLLECTIONS WHERE COLLECTION_NAME = ''ASSIGNED'''
