wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(33644013492072676)
,p_process_sequence=>30
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Create Product Request'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_result   VARCHAR2(5000);',
'    l_message  VARCHAR2(5000);',
'    l_suffix    VARCHAR2(10);',
'    header     json_object_t;',
'    j_object   json_object_t;',
'    j_array    json_array_t;',
'BEGIN',
'    header   := json_object_t();',
'    j_object := json_object_t();',
'    j_array  := json_array_t();',
'',
'    FOR i IN ( SELECT SEQ_ID, C001 AS PRODUCT_DEPENDENCY, C003 AS CITY, C004 AS CATEGORY, C005 AS SUB_CATEGORY, C006 AS MAKE, C007 AS MODEL,',
'                      C008 AS CLASS, C009 AS CHASSIS_NUMBER, C010 AS PLATE_NUMBER, C011 AS COLOR, C012 AS WALKWAY, C013 AS YEAR,',
'                      C014 AS FUEL_TYPE, C015 AS LOAD, C016 AS SERIAL_NUMBER, /*C017 AS STATUS,*/ C017 AS IS_DRAWED, C018 AS IS_BURNED,',
'                      C019 AS IS_ACCIDENT, C020 AS ISTEMARA_EXPIRATION, C021 AS PERIODIC_INSPECTION, C022 AS PREVIEW_TIMES,',
'                      C023 AS DESCRIPTION, C024 AS ADDRESS, C025 AS MAP_URL, C026 AS IMAGES_URLS, C027 AS MAIN_IMAGE_URL',
'                 FROM APEX_COLLECTIONS',
'                WHERE COLLECTION_NAME = ''ASSIGNED''',
'                  AND SEQ_ID > 1 )',
'    LOOP',
'        IF :P45_SELLER IS NULL OR i.MAKE IS NULL OR i.MODEL IS NULL OR i.YEAR IS NULL OR i.CHASSIS_NUMBER IS NULL THEN',
'            RAISE_APPLICATION_ERROR(-20007, SYSTEM_CONTROLS.get_translation(p_code => ''missing_data'', p_lang => ''ar''));',
'        END IF;',
'',
'        -- HANDEL BUDGET-2 & EARTH-GATE PRODUCT NAME SUFFIX',
'        IF :P45_SELLER IN (98, 102) THEN',
'            l_suffix := extract_number(i.PLATE_NUMBER);',
'        ELSE',
'            l_suffix := SUBSTR(TRIM(i.CHASSIS_NUMBER), - 6);',
'        END IF;',
'',
'        j_object.put(''seller_id'',           :P45_SELLER);',
'        j_object.put(''product_name'',        TRIM(i.MAKE) || '' '' || TRIM(i.MODEL) || '' '' || TRIM(i.YEAR) || '' - (VIN:'' || l_suffix || '')'');',
'        j_object.put(''product_dependency'',  i.PRODUCT_DEPENDENCY);',
'        j_object.put(''city'',                TRIM(i.CITY));',
'        j_object.put(''category'',            TRIM(i.CATEGORY));',
'        j_object.put(''sub_category'',        TRIM(i.SUB_CATEGORY));',
'        j_object.put(''make'',                TRIM(i.MAKE));',
'        j_object.put(''model'',               TRIM(i.MODEL));',
'        j_object.put(''class'',               TRIM(i.CLASS));',
'        j_object.put(''chassis_number'',      TRIM(i.CHASSIS_NUMBER));',
'        j_object.put(''plate_number'',        TRIM(i.PLATE_NUMBER));',
'        j_object.put(''color'',               TRIM(i.COLOR));',
'        j_object.put(''walkway'',             TRIM(i.WALKWAY));',
'        j_object.put(''year'',                TRIM(i.YEAR));',
'        j_object.put(''fuel_type'',           TRIM(i.FUEL_TYPE));',
'        j_object.put(''load'',                TRIM(i.LOAD));',
'        j_object.put(''serial_number'',       TRIM(i.SERIAL_NUMBER));',
'        -- j_object.put(''status'',              TRIM(i.STATUS));',
'        j_object.put(''is_drawed'',           TRIM(i.IS_DRAWED));',
'        j_object.put(''is_burned'',           TRIM(i.IS_BURNED));',
'        j_object.put(''is_accident'',         TRIM(i.IS_ACCIDENT));',
'        j_object.put(''istemara_expiration'', TRIM(i.ISTEMARA_EXPIRATION));',
'        j_object.put(''periodic_inspection'', TRIM(i.PERIODIC_INSPECTION));',
'        j_object.put(''preview_times'',       TRIM(i.PREVIEW_TIMES));',
'        j_object.put(''description'',         TRIM(i.DESCRIPTION));',
'        j_object.put(''address'',             TRIM(i.ADDRESS));',
'        j_object.put(''map_url'',             TRIM(i.MAP_URL));',
'        j_object.put(''images_urs'',          TRIM(i.IMAGES_URLS));',
'        j_object.put(''main_image_url'',      TRIM(i.MAIN_IMAGE_URL));',
'',
'        j_array.append(j_object); ',
'        j_object := json_object_t();',
'    END LOOP;',
'',
'    header.put(''items'', j_array);',
'',
'    l_result := SYSTEM_INTEGRATION.send_products (',
'                        p_body     => header.to_clob(),',
'                        p_message  => l_message',
'                    );',
'    ',
'    :P45_RESPONSE := l_message;',
'',
'    IF l_result <> ''1'' THEN',
'        RAISE_APPLICATION_ERROR(-20007, l_message);',
'    END IF;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(33640031724072671)
,p_process_success_message=>'The products Uploaded successfully'
,p_internal_uid=>17357881104822274
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(33643557929072675)
,p_process_sequence=>40
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Create Product Locally'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_id         NUMBER;',
'    v_seq        NUMBER;',
'    v_master_id  NUMBER;',
'    v_inserted   NUMBER;',
'BEGIN',
'    SELECT MAX(SEQUENCE) + 1 INTO v_seq FROM SELLER_ASSIGNED_FILES_MASTER;',
'',
'    INSERT INTO SELLER_ASSIGNED_FILES_MASTER ( SELLER_ID, USER_ID, SEQUENCE, NAME, FILE_ID, IS_ACTIVE, STATUS_ID )',
'        VALUES (:P45_SELLER, :P45_ASSIGNED_AGENT, v_seq, SELLER.seller_name(p_seller_id => :P45_SELLER), :P45_FILE_ID, 1,',
'                 LOOKUPS_MNT.lookup_detail_id_by_code (p_lookup_detail_code => ''done'', p_lookup_code => ''seller_assigned_files_status''))',
'    RETURNING ID INTO v_master_id;',
'',
'    IF SQL%ROWCOUNT = 0 THEN',
'        RAISE_APPLICATION_ERROR(-20001, ''ID => '' || v_master_id);',
'    END IF;',
'',
'    FOR i IN ( SELECT SEQ_ID, C001 AS PRODUCT_DEPENDENCY, C003 AS CITY, C004 AS CATEGORY, C005 AS SUB_CATEGORY, C006 AS MAKE, C007 AS MODEL,',
'                      C008 AS CLASS, C009 AS CHASSIS_NUMBER, C010 AS PLATE_NUMBER, C011 AS COLOR, C012 AS WALKWAY, C013 AS YEAR,',
'                      C014 AS FUEL_TYPE, C015 AS LOAD, C016 AS SERIAL_NUMBER, C017 AS IS_DRAWED, C018 AS IS_BURNED,',
'                      C019 AS IS_ACCIDENT, C020 AS ISTEMARA_EXPIRATION, C021 AS PERIODIC_INSPECTION, C022 AS PREVIEW_TIMES,',
'                      C023 AS DESCRIPTION, C024 AS ADDRESS, C025 AS MAP_URL, C026 AS IMAGES_URLS, C027 AS MAIN_IMAGE_URL',
'             FROM APEX_COLLECTIONS',
'            WHERE COLLECTION_NAME = ''ASSIGNED''',
'                  AND SEQ_ID > 1 )',
'    LOOP',
'        INSERT INTO SELLER_ASSIGNED_FILES_DETAILS (',
'                MASTER_ID, SELLER_ID, USER_ID, SEQUENCE, PRODUCT_DEPENDENCY, CITY, CATEGORY, SUB_CATEGORY, MAKE, MODEL, CLASS,',
'                CHASSIS_NUMBER, PLATE_NUMBER, COLOR, WALKWAY, YEAR, FUEL_TYPE, LOAD, SERIAL_NUMBER, IS_DRAWED, IS_BURNED, IS_ACCIDENT,',
'                ISTEMARA_EXPIRATION, PERIODIC_INSPECTION, PREVIEW_TIMES, DESCRIPTION, ADDRESS, MAP_URL, IMAGES_URLS, MAIN_IMAGE_URL',
'        ) VALUES ( ',
'                v_master_id, :P45_SELLER, :P45_ASSIGNED_AGENT, i.SEQ_ID - 1, i.PRODUCT_DEPENDENCY, i.CITY, i.CATEGORY, i.SUB_CATEGORY, i.MAKE, i.MODEL,',
'                i.CLASS, i.CHASSIS_NUMBER, i.PLATE_NUMBER, i.COLOR, i.WALKWAY, i.YEAR, i.FUEL_TYPE, i.LOAD, i.SERIAL_NUMBER,',
'                i.IS_DRAWED, i.IS_BURNED, i.IS_ACCIDENT, i.ISTEMARA_EXPIRATION, i.PERIODIC_INSPECTION, i.PREVIEW_TIMES,',
'                i.DESCRIPTION, i.ADDRESS, i.MAP_URL, i.IMAGES_URLS, i.MAIN_IMAGE_URL',
'        ) RETURNING ID INTO v_id;',
'',
'        IF SQL%ROWCOUNT = 0 THEN',
'            RAISE_APPLICATION_ERROR(-20003, ''Insertion Error with ID => '' || v_id);',
'        END IF;',
'',
'        FOR j IN (SELECT jt.success, jt.productId, jt.sellerId, jt.message',
'                    FROM',
'                    JSON_TABLE (:P45_RESPONSE,',
'                        ''$.results[*]''',
'                                COLUMNS (',
'                                    success     varchar2(500) path ''$.success'',',
'                                    productId   varchar2(500) path ''$.productId'',',
'                                    sellerId    varchar2(500) path ''$.sellerId'',',
'                                    message     varchar2(500) path ''$.message'',',
'                                    vinNumber   varchar2(500) path ''$.vinNumber''',
'                                )',
'                            ) AS jt',
'                     WHERE i.CHASSIS_NUMBER = jt.vinNumber)',
'        LOOP',
'            IF j.success = ''true'' THEN',
'                v_inserted := 1;',
'            ELSE',
'                v_inserted := 0;',
'            END IF;',
'',
'            UPDATE SELLER_ASSIGNED_FILES_DETAILS',
'               SET RES_PRODUCT_ID = j.productId,',
'                   RES_MESSAGE  = j.message,',
'                   IS_INSERTED  = v_inserted',
'             WHERE ID = v_id;',
'',
'            IF SQL%ROWCOUNT = 0 THEN',
'                RAISE_APPLICATION_ERROR(-20005, ''Updating Error with ID => '' || v_id);',
'            END IF;',
'        END LOOP;',
'    END LOOP;',
'',
'    APEX_COLLECTION.TRUNCATE_COLLECTION ( p_collection_name => ''ASSIGNED'' );',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_process_error_message=>'2-  #SQLERRM#'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(33640031724072671)
,p_process_success_message=>'The products Uploaded successfully'
,p_internal_uid=>17357425541822273
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(33643173465072675)
,p_process_sequence=>50
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_SESSION_STATE'
,p_process_name=>'Clear Session State'
