wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(34104801619539442)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Upload the main Image'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_file_names        APEX_T_VARCHAR2;',
'    l_file              APEX_APPLICATION_TEMP_FILES%ROWTYPE;',
'    l_file_name         VARCHAR2(255);',
'    l_request_url	    VARCHAR2(32767);',
'    l_result	        CLOB;',
'BEGIN',
'    l_file_names := apex_string.SPLIT (',
'                        p_str => :P46_MAIN_IMAGE,',
'                        p_sep => '':'' );',
'',
'    IF l_file_names.count = 0 THEN',
'        RAISE_APPLICATION_ERROR(-20001, ''You have to upload the main image'');',
'    END IF;',
'',
'    SELECT *',
'      INTO l_file',
'      FROM APEX_APPLICATION_TEMP_FILES',
'     WHERE NAME = :P46_MAIN_IMAGE;',
'',
'    l_file_name := TO_CHAR(get_current_date, ''YY'') ',
'                        || DBMS_RANDOM.STRING(''x'', 8)',
'                        || SYSTEM_CONTROLS.file_extension_by_mimetype(p_mimetype => l_file.MIME_TYPE);',
'',
'    l_request_url := :G_OCI_BASE_URL||''/b/seller-assign/o/'' || l_file_name;',
'    ',
'    l_result := APEX_WEB_SERVICE.make_rest_request (',
'                    p_url                  => l_request_url,',
'                    p_http_method          => ''PUT'',',
'                    p_body_blob            => l_file.BLOB_CONTENT,',
'                    p_credential_static_id => ''OCI_AUTH''',
'                );',
'',
'    IF APEX_WEB_SERVICE.g_status_code NOT IN ( 200, 201, 202, 203, 204, 205, 206, 207, 226 ) THEN',
'        SYSTEM_CONTROLS.ERROR_LOGS ( p_error_type    => ''SYSTEM_ERROR'',',
'                                     p_process_name  => ''OCI_OS.put_object - App: '' || :APP_ID || '' - Page: '' || :APP_PAGE_ID,',
'                                     p_error_code    => -2,',
'                                     p_error_message => SUBSTR(l_result, 1, 4000),',
'                                     p_logger_name   => :APP_USER',
'                                );',
'        RAISE_APPLICATION_ERROR(-20002, ''Error with uploading Data!'');',
'    END IF;',
'',
'    :P46_MAIN_IMAGE_URL := l_request_url;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>'P46_MAIN_IMAGE'
,p_process_when_type=>'ITEM_IS_NOT_NULL'
,p_internal_uid=>17818669232289040
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(34104837707539443)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Upload Product Images'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_file_name    VARCHAR2(255);',
'    l_request_url  VARCHAR2(32767);',
'    l_result	   CLOB;',
'BEGIN',
'    FOR i IN (SELECT c001 AS FILE_NAME, c002 AS MIME_TYPE, blob001 AS BLOB_CONTENT FROM apex_collections WHERE collection_name = ''DROPZONE_UPLOAD'') LOOP',
'        l_file_name := TO_CHAR(get_current_date, ''YY'') ',
'                            || DBMS_RANDOM.STRING(''x'', 8)',
'                            || SYSTEM_CONTROLS.file_extension_by_mimetype(p_mimetype => i.MIME_TYPE);',
'',
'        l_request_url := :G_OCI_BASE_URL||''/b/seller-assign/o/''||l_file_name;',
'',
'        l_result := APEX_WEB_SERVICE.make_rest_request (',
'                        p_url                  => l_request_url,',
'                        p_http_method          => ''PUT'',',
'                        p_body_blob            => i.BLOB_CONTENT,',
'                        p_credential_static_id => ''OCI_AUTH''',
'                    );',
'',
'        IF APEX_WEB_SERVICE.g_status_code NOT IN ( 200, 201, 202, 203, 204, 205, 206, 207, 226 ) THEN',
'            SYSTEM_CONTROLS.ERROR_LOGS ( p_error_type    => ''SYSTEM_ERROR'',',
'                                         p_process_name  => ''OCI_OS.put_object - App: '' || :APP_ID || '' - Page: '' || :APP_PAGE_ID,',
'                                         p_error_code    => -2,',
'                                         p_error_message => SUBSTR(l_result, 1, 4000),',
'                                         p_logger_name   => :APP_USER',
'                                    );',
'            RAISE_APPLICATION_ERROR(-20002, ''Error with uploading Data!'');',
'        END IF;',
'',
'        :P46_IMAGES_URLS := :P46_IMAGES_URLS || l_request_url || '','';',
'    END LOOP;',
'    ',
'    :P46_IMAGES_URLS := ''['' || SUBSTR(:P46_IMAGES_URLS, 1, LENGTH(:P46_IMAGES_URLS) - 1) || '']'';',
'',
'    -- TRUNCATE THE COLLECTION AFTER GET THE URLS',
'    APEX_COLLECTION.TRUNCATE_COLLECTION (p_collection_name => ''DROPZONE_UPLOAD'');',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>'SELECT 1 FROM apex_collections WHERE collection_name = ''DROPZONE_UPLOAD'''
,p_process_when_type=>'EXISTS'
,p_internal_uid=>17818705320289041
);
