wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(34221591855278936)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'ADD USER'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_user_id    NUMBER;',
'    v_role_id    NUMBER;',
'    v_agent_type VARCHAR2(255);',
'BEGIN',
'    INSERT INTO APP_USERS ( CLIENT_ID_NO, PERSONAL_NAME, PHONE, WHATS_PHONE, USER_NAME, PASSWORD, EMAIL_ADDRESS, START_DATE, ALLOW_CHANGE_PASS, CHANGE_PASS_NEXT_LOGIN, ACTIVE_FLAG,',
'                            USER_LANGUAGE_ID, USER_TYPE, OBJECT_TYPE, OBJECT_VALUE )',
'        VALUES ( :P48_IDENTITY_NUMBER, :P48_NAME_AR, :P48_PHONE, :P48_WHATS, :P48_IDENTITY_NUMBER, APP_USER_SECURITY.get_hash(:P48_IDENTITY_NUMBER, :P48_IDENTITY_NUMBER),',
'                 :P48_EMAIL, GET_CURRENT_DATE, ''Y'', ''Y'', ''Y'', 1, LOOKUPS_MNT.lookup_detail_id_by_code (p_lookup_detail_code => ''agent'', p_lookup_code => ''user_type''),',
'                 LOOKUPS_MNT.lookup_detail_id_by_code (p_lookup_detail_code => ''agent'', p_lookup_code => ''user_type''), :P48_ID )',
'    RETURNING ID INTO v_user_id;',
'',
'    IF SQL%ROWCOUNT = 0 THEN',
'        RAISE_APPLICATION_ERROR(-20001, ''User Creation Error'');',
'    END IF;',
'',
'    -- ADD USER ROLE',
'    v_agent_type := LOOKUPS_MNT.lookup_detail_code_by_id (p_lookup_detail_id => :P48_AGENT_TYPE);',
'',
'    IF v_agent_type = ''washing'' OR v_agent_type = ''photography'' OR v_agent_type = ''washing_photographing'' THEN',
'        v_role_id := APP_USER_SECURITY.role_id_by_name(''Assigned Agent'');',
'    ELSIF v_agent_type = ''exhibition'' THEN',
'        v_role_id := APP_USER_SECURITY.role_id_by_name(''Exhibition Agent'');',
'    ELSIF v_agent_type = ''transfer_ownership'' THEN',
'        v_role_id := APP_USER_SECURITY.role_id_by_name(''Transfer Ownership'');',
'    ELSE',
'        RAISE_APPLICATION_ERROR(-20001, ''You Should choose an available role'');',
'    END IF;',
'',
'    INSERT INTO APP_USER_ROLES ( USER_ID, ROLE_ID, ENABLE_FLAG, START_DATE )',
'        VALUES ( v_user_id, v_role_id, ''Y'', GET_CURRENT_DATE );',
'',
'    IF SQL%ROWCOUNT = 0 THEN',
'        RAISE_APPLICATION_ERROR(-20001, ''Role Creation Error'');',
'    END IF;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(34209152814278925)
,p_internal_uid=>17935459468028534
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(34221995429278936)
,p_process_sequence=>30
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'UPDATE USER'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_user_id    NUMBER;',
'    v_role_id    NUMBER;',
'    v_agent_type VARCHAR2(255);',
'BEGIN',
'    SELECT ID',
'      INTO v_user_id',
'      FROM APP_USERS',
'     WHERE OBJECT_VALUE = :P48_ID',
'       AND OBJECT_TYPE  = LOOKUPS_MNT.lookup_detail_id_by_code (p_lookup_detail_code => ''agent'', p_lookup_code => ''user_type'');',
'',
'    -- UPDATE USER',
'    UPDATE APP_USERS',
'       SET CLIENT_ID_NO  = :P48_IDENTITY_NUMBER,',
'           PERSONAL_NAME = :P48_NAME_AR,',
'           PHONE         = :P48_PHONE,',
'           WHATS_PHONE   = :P48_WHATS,',
'           EMAIL_ADDRESS = :P48_EMAIL,',
'           ACTIVE_FLAG   = DECODE(:P48_IS_ACTIVE, 1, ''Y'', ''N'')',
'     WHERE ID = v_user_id;',
'',
'    IF SQL%ROWCOUNT = 0 THEN',
'        RAISE_APPLICATION_ERROR(-20001, ''User Modification Error'');',
'    END IF;',
'',
'    -- UPDATE USER ROLE',
'    v_agent_type := LOOKUPS_MNT.lookup_detail_code_by_id (p_lookup_detail_id => :P48_AGENT_TYPE);',
'',
'    IF v_agent_type = ''washing'' OR v_agent_type = ''photography'' OR v_agent_type = ''washing_photographing'' THEN',
'        v_role_id := APP_USER_SECURITY.role_id_by_name(''Assigned Agent'');',
'    ELSIF v_agent_type = ''exhibition'' THEN',
'        v_role_id := APP_USER_SECURITY.role_id_by_name(''Exhibition Agent'');',
'    ELSIF v_agent_type = ''transfer_ownership'' THEN',
'        v_role_id := APP_USER_SECURITY.role_id_by_name(''Transfer Ownership'');',
'    ELSE',
'        RAISE_APPLICATION_ERROR(-20001, ''You Should choose an available role'');',
'    END IF;',
'',
'    UPDATE APP_USER_ROLES',
'       SET ROLE_ID = v_role_id',
'     WHERE USER_ID = v_user_id;',
'',
'    IF SQL%ROWCOUNT = 0 THEN',
'        RAISE_APPLICATION_ERROR(-20001, ''Role Modification Error'');',
'    END IF;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(34210347206278926)
,p_internal_uid=>17935863042028534
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(34222818567278937)
,p_process_sequence=>40
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'DELETE'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_user_id  NUMBER;',
'BEGIN',
'    SELECT ID',
'      INTO v_user_id',
'      FROM APP_USERS',
'     WHERE OBJECT_VALUE = :P48_ID',
'       AND OBJECT_TYPE  = LOOKUPS_MNT.lookup_detail_id_by_code (p_lookup_detail_code => ''agent'', p_lookup_code => ''user_type'');',
'',
'    -- DELETE ROLE',
'    DELETE FROM APP_USER_ROLES WHERE USER_ID = v_user_id;',
'',
'    IF SQL%ROWCOUNT = 0 THEN',
'        RAISE_APPLICATION_ERROR(-20001, ''Role Delation Error'');',
'    END IF;',
'',
'    -- DELETE USER',
'    DELETE FROM APP_USERS WHERE ID = v_user_id;',
'',
'    IF SQL%ROWCOUNT = 0 THEN',
'        RAISE_APPLICATION_ERROR(-20001, ''User Delation Error'');',
'    END IF;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(34209574867278925)
