wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(36327078333742111)
,p_event_id=>wwv_flow_imp.id(36326704306742107)
,p_event_result=>'TRUE'
,p_action_sequence=>20
,p_execute_on_page_init=>'N'
,p_name=>'update ticket table'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_result     NUMBER;',
'    l_message    VARCHAR2(500);',
'    l_email      VARCHAR2(500);',
'    l_status     VARCHAR2(500);',
'    l_status_id  NUMBER;',
'    l_resolved_id NUMBER;',
'BEGIN',
'    UPDATE TICKETS ',
'    SET STATUS = :P49_CHANGE_STATUS_ID',
'    WHERE ID = :P49_TICKET_ID;',
'',
'    IF SQL%ROWCOUNT = 0 THEN',
'        RAISE_APPLICATION_ERROR(-20001, SQLERRM);',
'    END IF;',
'',
'    SELECT LOOKUPS_MNT.lookup_detail_name_by_id (p_lookup_detail_id => STATUS , p_lang => ''ar''), STATUS, LOOKUPS_MNT.lookup_detail_id_by_code (p_lookup_detail_code => ''resolved_ticket'' , p_lookup_code => ''ticket_status'') ',
'      INTO l_status, l_status_id, l_resolved_id',
'      FROM TICKETS',
'     WHERE ID = :P49_TICKET_ID;',
'',
'    IF SQL%ROWCOUNT = 0 THEN',
'        RAISE_APPLICATION_ERROR(-20002, SQLERRM);',
'    END IF;',
'',
'    IF l_status_id = l_resolved_id THEN',
'        -- SEND EMAIL',
'        BEGIN',
'            SELECT BUYER_EMAIL INTO l_email',
'              FROM TICKETS',
'             WHERE ID = :P49_TICKET_ID;',
'             ',
'        EXCEPTION',
'            WHEN NO_DATA_FOUND THEN',
'                l_email := ''a.awad@mobasher.sa'';',
'        END;',
'',
'        l_result := SYSTEM_CONTROLS.send_email ( ',
'                        p_to       => l_email,',
unistr('                        p_subject  => '' \062D\0627\0644\0629 \0627\0644\062A\0630\0643\0631\0629 '' || ''T-'' || LPAD(:P49_TICKET_ID, 6, 0),'),
unistr('                        p_html     => '' \062D\0627\0644\0629 \062A\0630\0643\0631\062A\0643 \0627\0644\0627\0646 \0647\064A :'' || l_status || '' ,\0644\0645\0632\064A\062F \0645\0646 \0627\0644\062A\0641\0627\0635\064A\0644 \0627\0644\0631\062C\0627\0621 \0632\064A\0627\0631\0629 \0627\0644\0645\0648\0642\0639 \0627\0644\0625\0644\0643\062A\0631\0648\0646\064A \0644\0645\0628\0627\0634\0631 \0644\0644\0645\0632\0627\062F\0627\062A'','),
'                        p_message  => l_message',
'                    );',
'',
'        IF l_result <> 1 THEN',
'            RAISE_APPLICATION_ERROR (-20005, l_message);',
'        END IF;',
'    END IF;',
'',
'',
'END;'))
,p_attribute_02=>'P49_CHANGE_STATUS_ID,P49_TICKET_ID'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
