wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(35013931245560440)
,p_event_id=>wwv_flow_imp.id(35013826961560439)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_name=>'Insert the comment'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_result    NUMBER;',
'    l_message   VARCHAR2(500);',
'    l_email     VARCHAR2(500);',
'    l_count     NUMBER;',
'BEGIN',
'    SELECT COUNT(ID)',
'      INTO l_count',
'      FROM TICKET_CHAT',
'     WHERE TICKET_ID = :P51_TICKET_ID',
'       AND CREATED_BY IN (SELECT UPPER(a.USER_NAME)',
'                            FROM MOBASHER_EMPLOYEES e, APP_USERS a',
'                           WHERE a.ID(+) = e.USER_ID);',
'',
'    INSERT INTO TICKET_CHAT(TICKET_ID, TEXT, CREATED_BY)',
'        VALUES (:P51_TICKET_ID, :P51_COMMENT_INPUT, nvl(v(''APP_USER''), user));',
'    ',
'    IF SQL%ROWCOUNT = 0 THEN',
unistr('        RAISE_APPLICATION_ERROR (-20001, ''\062E\0637\0623 \0641\064A \0625\0631\0633\0627\0644 \0627\0644\062A\0639\0644\064A\0642'');'),
'    END IF;',
'',
'    IF l_count = 0 THEN',
'        -- SEND EMAIL',
'        BEGIN',
'            SELECT BUYER_EMAIL INTO l_email',
'              FROM TICKETS',
'             WHERE ID = :P51_TICKET_ID;',
'             ',
'        EXCEPTION',
'            WHEN NO_DATA_FOUND THEN',
'                l_email := ''a.awad@mobasher.sa'';',
'        END;',
'',
'        l_result := SYSTEM_CONTROLS.send_email ( ',
'                        p_to       => l_email,',
unistr('                        p_subject  => ''\062A\0630\0643\0631\0629 \0631\0642\0645 : ''|| ''T-'' || LPAD(:P51_TICKET_ID, 6, 0) ,'),
unistr('                        p_html     => ''\062A\0645 \0627\0644\0631\062F \0639\0644\0649 \062A\0630\0643\0631\062A\0643 \0631\0642\0645 : '' || ''T-'' || LPAD(:P51_TICKET_ID, 6, 0) || '', '' || '' \0644\0645\0632\064A\062F \0645\0646 \0627\0644\062A\0641\0627\0635\064A\0644 \0627\0644\0631\062C\0627\0621 \0632\064A\0627\0631\0629 \0627\0644\0648\0642\0639 \0627\0644\0625\0644\0643\062A\0631\0648\0646\064A \0644\0645\0628\0627\0634\0631 \0644\0644\0645\0632\0627\062F\0627\062A '','),
'                        p_message  => l_message',
'                    );',
'',
'        IF l_result <> 1 THEN',
'            RAISE_APPLICATION_ERROR (-20005, l_message);',
'        END IF;',
'    END IF;',
'END;'))
,p_attribute_02=>'P51_TICKET_ID,P51_COMMENT_INPUT'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
