 p_id=>wwv_flow_imp.id(124871356206438727)
,p_plug_name=>'SELLERS'
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(86286645774821557)
,p_plug_display_sequence=>20
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    to_number(id) id,',
'    (',
'        CASE',
'            WHEN nvl(containersno, 0) = 0 THEN',
'                NULL',
'            ELSE',
'                ''<span class="fa fa-eye" aria-hidden="true"></span>''',
'        END',
'    )            more,',
'    name,',
'    auctionsno,',
'    containersno,',
'    successfulauctionsno,',
'    pendingauctionsno,',
unistr('    DECODE (sellerCategory , ''REAL_ESTATES'', decode(:P_LANG,''ar'',''\0639\0642\0627\0631\0627\062A'' ,''REAL ESTATES''), '),
unistr('                             ''VEHICLES'', decode(:P_LANG,''ar'',''\0645\0646\0642\0648\0644\0627\062A'' ,''VEHICLES''), '),
unistr('                             ''ANIMALS'', decode(:P_LANG,''ar'',''\062D\064A\0648\0627\0646\0627\062A'' ,''ANIMALS''), '),
'                             ''''',
'    ) AS sellerCategory,',
'     AuctionsNotpayed  ,',
'    ProductsNotpayed ,',
'    null chat,',
'    null contract,',
'    null WALLET,',
'    trunc(LastAuctionContainerDate) LastAuctionContainerDate,',
'    LastAuctionContainerDate LastAuctionDate,',
'    (CASE WHEN trunc(LastAuctionContainerDate) <= trunc(sysdate)      and trunc(LastAuctionContainerDate) > trunc(sysdate - 30) THEN ''u-success-bg'' ',
'          WHEN trunc(LastAuctionContainerDate) <= trunc(sysdate - 30 )and trunc(LastAuctionContainerDate) > trunc(sysdate - 60) THEN ''u-warning-bg'' ',
'          WHEN trunc(LastAuctionContainerDate) <= trunc(sysdate - 60 )and trunc(LastAuctionContainerDate) > trunc(sysdate - 90) THEN ''u-color-8-bg'' ',
'          ELSE ''u-danger-bg''',
'     END ',
'    ) status,',
'    round(SUM(nvl(successfulauctionsno, 0)) / SUM(',
'        CASE',
'            WHEN auctionsno IS NULL',
'                 OR auctionsno = 0 THEN',
'                1',
'            ELSE',
'                auctionsno',
'        END',
'    ) * 100, 3) || '' % '' sale_percentage',
'FROM',
'    TABLE ( get_sellers_data )',
'GROUP BY',
'    id,',
'    name,',
'    auctionsno,',
'    containersno,',
'    successfulauctionsno,',
'    pendingauctionsno,',
'    sellerCategory,',
'     AuctionsNotpayed  ,',
'    ProductsNotpayed ,',
'    LastAuctionContainerDate;'))
,p_plug_source_type=>'NATIVE_IR'
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
