 p_id=>wwv_flow_imp.id(103353896646927624)
,p_plug_name=>'AUCTIONS DETAILS'
,p_region_name=>'AUCTIONS_DETAILS'
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_region_attributes=>'style="display:none"'
,p_plug_template=>wwv_flow_imp.id(86286645774821557)
,p_plug_display_sequence=>70
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'    SELECT',
unistr('     DECODE (status,   ''LIVE_NOW'', decode(:P_LANG,''ar'',''\0645\0628\0627\0634\0631 \0627\0644\0627\0646'' ,''LIVE NOW''), '),
unistr('                       ''SOLD'', decode(:P_LANG,''ar'',''\0645\064F\0628\0627\0639'' ,''SOLD''), '),
unistr('                       ''SOLD_BUY_NOW'', decode(:P_LANG,''ar'',''\0628\064A\0639\062A \0634\0631\0627\0621 \0627\0644\0622\0646'' ,''SOLD BUY NOW''), '),
unistr('                       ''PASS'', decode(:P_LANG,''ar'',''\0644\0645 \064A\0628\0627\0639'' ,''PASS''),'),
unistr('                       ''OFFER'', decode(:P_LANG,''ar'',''\0639\0631\0636'' ,''OFFER''),'),
unistr('                       ''PAYMENT_PENDING'', decode(:P_LANG,''ar'',''\0627\0646\062A\0638\0627\0631 \0627\0644\062F\0641\0639'' ,''PAYMENT PENDING''),'),
unistr('                       ''WAITING_INFATH_RESPONSE'', decode(:P_LANG,''ar'',''\0625\0646\062A\0638\0627\0631 \0631\062F \0625\0646\0641\0627\0630'' ,''WAITING INFATH RESPONSE''),'),
'                       '''') status,',
'    product_id,',
'    buyer_id buyer,',
'    ar_sa,',
'    sakNo,',
unistr('    regexp_replace( extract_varchar(ar_sa),''(\0631\0642\0645 \0627\0644\0635\0643|\0631\0642\0645 \0635\0643)'', '''' )   Product_Name ,'),
'    startprice,',
'    lastbid,',
unistr('    DECODE (paymentstatus,   ''NOT_YET'', decode(:P_LANG,''ar'',''\0644\0645 \064A\062A\0645 \0627\0644\062F\0641\0639'' ,''NOT YET''), '),
unistr('                             ''BUYER_SEND'', decode(:P_LANG,''ar'',''\0625\0631\0633\0627\0644 \0627\0644\0645\0634\062A\0631\064A'' ,''BUYER SEND''), '),
unistr('                             ''SELLER_CONFIRMED'', decode(:P_LANG,''ar'',''\0623\0643\062F \0627\0644\0628\0627\0626\0639'' ,''SELLER CONFIRMED''), '),
unistr('                             ''PAYMENT_DONE'', decode(:P_LANG,''ar'',''\062A\0645 \0627\0644\062F\0641\0639'' ,''PAYMENT DONE''),'),
unistr('                             ''PAYMENT_PENDING'', decode(:P_LANG,''ar'',''\0627\0646\062A\0638\0627\0631 \0627\0644\062F\0641\0639'' ,''PAYMENT PENDING''),'),
unistr('                             ''BUYER_RENEGED'', decode(:P_LANG,''ar'',''\062A\0645 \062A\062C\062F\064A\062F \0627\0644\0645\0634\062A\0631\064A'' ,''BUYER RENEGED''),'),
'                             '''') paymentstatus,',
'    subtotal,',
'    totalprice,',
'    totaldiscount,',
'    (CASE WHEN status LIKE ''%SOLD%''  THEN APEX_ITEM.CHECKBOX2(1,product_id || '':'' ||id,''UNCHECKED'' )   ELSE null END )  "SELECT",',
'    (case when istransfertoinfath = ''true'' then ''u-success-bg'' else ''u-warning-bg'' end ) istransfertoinfath_color ,',
'',
unistr('    (case  when type not like ''%INFATH%'' then decode(:P_LANG,''ar'',''\0644\064A\0633 \062A\0627\0628\0639 \0644\0625\0646\0641\0627\0630'' ,''Not related to infath'')  '),
unistr('           when type  like ''%INFATH%'' and status like ''%PASS%'' then decode(:P_LANG,''ar'',''\0644\0645 \064A\0628\0627\0639 \0627\0644\0645\0632\0627\062F'' ,''Auction pass'')  '),
unistr('           else decode(istransfertoinfath,''true'',decode(:P_LANG,''ar'',''\0646\0639\0645'' ,''Yes'') ,decode(:P_LANG,''ar'',''\0644\0627'' ,''No'')) end)   istransfertoinfath ,'),
'',
unistr('    SUM((case when item_ar_SA like ''%\0633\0639\0631 \0627\0644\0631\0628\062D%'' then nvl(item_totalPrice,0) else 0 end))   won_price,'),
unistr('    SUM((CASE WHEN item_ar_sa LIKE ''%\0633\0639\064A%''       THEN nvl( item_totalprice, 0) ELSE 0 END )) agent_price,'),
'    (CASE WHEN status LIKE ''%SOLD%''  THEN ''<span aria-hidden="true" class="fa fa-clipboard-list"></span>'' ELSE null END )                      details ,',
'    (CASE WHEN status LIKE ''%SOLD%'' THEN ''u-success-bg'' when status LIKE ''%LIVE_NOW%'' then ''u-warning-bg'' when status LIKE ''%PASS%'' then ''u-color-39-bg'' ELSE ''u-info-bg'' END ) status_color,',
'    -- (CASE WHEN buyer is not null  THEN ''<span aria-hidden="true" class="fa fa-user"></span>''  ELSE null END ) buyer_icon',
'    (CASE WHEN status LIKE ''%SOLD%''  THEN buyer_name || '' ''||secondname || '' ''||thirdname|| '' ''||fourthname   ELSE null END ) buyer_icon',
'',
'',
'FROM',
'    -- TABLE ( get_sellerauctions_data(:P53_ID) ) WHERE  auctioncontainer_id = :P53_AUCTIONCONTAINER_ID',
'    TABLE ( get_sellerauctions_finance_data (:P53_ID) ) WHERE  auctioncontainer_id = :P53_AUCTIONCONTAINER_ID',
'',
'    group by status ,',
'    product_id ,',
'    buyer_id ,',
'    ar_sa ,',
'    sakNo ,',
'    startPrice ,',
'    lastBid ,',
'    isTransferToInfath,',
'    paymentStatus ,',
'    subTotal ,',
'    totalPrice ,',
'    totalDiscount,',
'    type,',
'    id,',
'    buyer_name,',
'    secondname ,thirdname,fourthname',
'',
'    order by  status desc'))
,p_plug_source_type=>'NATIVE_IR'
,p_ajax_items_to_submit=>'P53_ID,P53_AUCTIONCONTAINER_ID'
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
,p_prn_width=>11
,p_prn_height=>8.5
