,p_plug_display_sequence=>60
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'/*SELECT',
'    id,',
'    successfulproductscount,',
'    productscount,',
'    name,',
'    type,',
'    round(( successfulproductscount / productscount * 100 ),3)|| '' % ''                 sale_percentage,',
'    auctioncontainer_id,',
'    SUM(nvl(won_price, 0))   won_price,',
'    SUM(nvl(agent_price, 0)) agent_price ,       ',
'    null as details from (        ',
'',
'    SELECT',
'    distinct id,',
'    successfulproductscount,',
'    productscount,',
'    name,',
'    type,',
'    auctioncontainer_id,',
unistr('    (case when item_ar_SA like ''%\0633\0639\0631 \0627\0644\0631\0628\062D%'' then SUM(nvl(item_totalPrice,0)) else 0end) won_price,'),
unistr('    (CASE WHEN item_ar_sa LIKE ''%\0633\0639\064A%''       THEN SUM( nvl( item_totalprice, 0)) ELSE 0 END ) agent_price          '),
'FROM',
'    TABLE ( get_sellerauctions_data(:P53_ID) ) ',
'',
'    ',
'    group by id,',
'    successfulproductscount,',
'    productscount,',
'    name,',
'    type,',
'    auctioncontainer_id,',
'    item_ar_SA',
'',
'    )  group by id,',
'    successfulproductscount,',
'    productscount,',
'    name,',
'    type,',
'    auctioncontainer_id*/',
'',
'  SELECT',
'    id,',
'    successfulproductscount,',
'    productscount,',
'    name,',
unistr('     DECODE (type        ,   ''TIMED'', decode(:P_LANG,''ar'',''\0632\0645\0646\064A'' ,''TIMED''), '),
unistr('                             ''INFATH_TIMED'', decode(:P_LANG,''ar'',''\0625\0646\0641\0627\0630 \0632\0645\0646\064A'' ,''INFATH TIMED''), '),
unistr('                             ''SAR_TIMED'', decode(:P_LANG,''ar'',''\0627\0644\062E\0637\0648\0637 \0627\0644\062D\062F\064A\062F\064A\0629 \0627\0644\0633\0639\0648\062F\064A\0629 \0632\0645\0646\064A'' ,''SAR TIMED''), '),
unistr('                             ''INFATH_LIVE'', decode(:P_LANG,''ar'',''\0625\0646\0641\0627\0630 \0647\062C\064A\0646'' ,''INFATH LIVE''),'),
unistr('                             ''TIMED_LIVE'', decode(:P_LANG,''ar'',''\0647\062C\064A\0646 \0632\0645\0646\064A'' ,''TIMED LIVE''),'),
unistr('                             ''LIVE'', decode(:P_LANG,''ar'',''\0647\062C\064A\0646'' ,''LIVE''),'),
'                             '''')type,',
'    round(( successfulproductscount / productscount * 100 ),3)|| '' % ''                 sale_percentage,',
'    auctioncontainer_id,',
'    SUM(nvl(won_price, 0))   won_price,',
'    SUM(nvl(agent_price, 0)) agent_price ,       ',
'    null as details ,        ',
'    null as Close ,',
'    :P53_ID as specified_payment ',
'    ',
'    ',
'    from (        ',
'',
'    SELECT',
'      id,',
'    successfulproductscount,',
'    productscount,',
'    name,',
'    type,',
'    auctioncontainer_id,',
unistr('    (case when item_ar_SA like ''%\0633\0639\0631 \0627\0644\0631\0628\062D%'' then nvl(item_totalPrice,0) else 0 end) won_price,'),
unistr('    (CASE WHEN item_ar_sa LIKE ''%\0633\0639\064A%''       THEN nvl( item_totalprice, 0) ELSE 0 END ) agent_price          '),
'FROM',
'    TABLE ( get_sellerauctions_data(:P53_ID) ) ',
'',
'    )  group by id,',
'    successfulproductscount,',
'    productscount,',
'    name,',
'    type,',
'    auctioncontainer_id'))
,p_plug_source_type=>'NATIVE_IR'
