,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'/*SELECT',
'    totalcontainers,',
'    SUM(nvl(successfulproductscount, 0)) successfulproductscount,',
'    SUM(nvl(productscount, 0))           productscount,',
'    SUM(nvl(won_price, 0))               total_won_price,',
'    SUM(nvl(agent_price, 0))             total_agent_price ,       ',
'    ROUND ( (SUM(nvl(successfulproductscount, 0)) /  SUM(nvl(productscount, 0))  ) * 100 ,3) ||'' % ''      Sale_Percentage from (        ',
'   select TOTALCONTAINERS,SUCCESSFULPRODUCTSCOUNT,ID,PRODUCTSCOUNT,SUM(nvl(WON_PRICE,0)) WON_PRICE,SUM(nvl(AGENT_PRICE ,0)) AGENT_PRICE from (        ',
'',
'    SELECT',
'           distinct totalContainers  ,ID,',
'           successfulproductscount ,',
'            productscount ,',
unistr('             (case when item_ar_SA like ''%\0633\0639\0631 \0627\0644\0631\0628\062D%'' then SUM(nvl(item_totalPrice,0)) else 0end) won_price,'),
unistr('             (CASE WHEN item_ar_sa LIKE ''%\0633\0639\064A%''       THEN SUM( nvl( item_totalprice, 0)) ELSE 0 END ) agent_price  '),
'            ',
'FROM',
'    TABLE ( get_sellerauctions_data(:P53_ID) ) ',
'',
'    ',
'    group by totalContainers  ,ID,',
'           successfulproductscount ,',
'            productscount ,item_ar_SA',
'    ',
'    )  group by TOTALCONTAINERS,SUCCESSFULPRODUCTSCOUNT,PRODUCTSCOUNT,id) GROUP BY TOTALCONTAINERS*/',
'    SELECT',
'    totalcontainers,',
'    SUM(nvl(successfulproductscount, 0)) successfulproductscount,',
'    SUM(nvl(productscount, 0))           productscount,',
'    SUM(nvl(won_price, 0))               total_won_price,',
'    SUM(nvl(agent_price, 0))             total_agent_price ,       ',
'    ROUND ( (SUM(nvl(successfulproductscount, 0)) /  SUM(nvl(productscount, 0))  ) * 100 ,3) ||'' % ''      Sale_Percentage from (        ',
'   select TOTALCONTAINERS,SUCCESSFULPRODUCTSCOUNT,ID,PRODUCTSCOUNT,SUM(nvl(WON_PRICE,0)) WON_PRICE,SUM(nvl(AGENT_PRICE ,0)) AGENT_PRICE from (        ',
'',
'    SELECT',
'            totalContainers  ,ID,',
'           successfulproductscount ,',
'            productscount ,',
unistr('             (case when item_ar_SA like ''%\0633\0639\0631 \0627\0644\0631\0628\062D%'' then nvl(item_totalPrice,0) else 0 end) won_price,'),
unistr('             (CASE WHEN item_ar_sa LIKE ''%\0633\0639\064A%''       THEN  nvl( item_totalprice, 0) ELSE 0 END ) agent_price  '),
'            ',
'FROM',
'    TABLE ( get_sellerauctions_data(:P53_ID) ) )',
'',
'    ',
'   group by TOTALCONTAINERS,SUCCESSFULPRODUCTSCOUNT,PRODUCTSCOUNT,id) GROUP BY TOTALCONTAINERS'))
,p_ajax_enabled=>'Y'
,p_ajax_items_to_submit=>'P53_ID'
