'APEX_COLLECTION.CREATE_OR_TRUNCATE_COLLECTION(',
'    p_collection_name => ''PRODUCT_CHECK_FOR_PAY'');',
'',
'',
'else',
'null;',
'',
'end if;',
'',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>41244768935380244
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(57530964988630647)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'GET_PRODUCT_CHECK_FOR_PAY'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_exists BOOLEAN;',
'    v_item   NUMBER;',
'    p_seq    NUMBER;',
'BEGIN',
'',
'    l_exists := apex_collection.collection_exists(p_collection_name => ''PRODUCT_CHECK_FOR_PAY'');',
'    IF l_exists = false THEN',
'        apex_collection.create_or_truncate_collection(p_collection_name => ''PRODUCT_CHECK_FOR_PAY'');',
'    END IF;',
'',
'    FOR i IN (',
'        SELECT',
'            COUNT(*) AS counts',
'        FROM',
'            apex_collections',
'        WHERE',
'            collection_name = ''PRODUCT_CHECK_FOR_PAY''',
'            AND c001 = apex_application.g_x01',
'            AND c003 = apex_application.g_x03',
'            ',
'    ) LOOP',
'',
'        IF i.counts = 0 THEN',
'            apex_collection.add_member(',
'                                      p_collection_name => ''PRODUCT_CHECK_FOR_PAY'',',
'                                      p_c001            => apex_application.g_x01,',
'                                      p_c002            => apex_application.g_x02,',
'                                      p_c003            => apex_application.g_x03',
'            );',
'',
'        ELSE',
'',
'            SELECT',
'                seq_id',
'            INTO p_seq',
'            FROM',
'                apex_collections',
'            WHERE',
'                collection_name = ''PRODUCT_CHECK_FOR_PAY''',
'                AND c001 = apex_application.g_x01',
'                AND c003 = apex_application.g_x03;',
'',
'            apex_collection.update_member(',
'                                         p_collection_name => ''PRODUCT_CHECK_FOR_PAY'',',
'                                         p_seq             => p_seq,',
'                                         p_c001            => apex_application.g_x01,',
'                                         p_c002            => apex_application.g_x02,',
'                                         p_c003            => apex_application.g_x03',
'            );',
'',
'        END IF;',
'    END LOOP;',
'',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>41244832601380245
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(57531211969630649)
,p_process_sequence=>20
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'GET_ALL_PRODUCT_CHECK_FOR_PAY'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_exists BOOLEAN;',
'    v_item   NUMBER;',
'    p_seq    NUMBER;',
'    v_counts    NUMBER;',
'BEGIN',
'',
'    l_exists := apex_collection.collection_exists(p_collection_name => ''PRODUCT_CHECK_FOR_PAY'');',
'    IF l_exists = false THEN',
'        apex_collection.create_or_truncate_collection(p_collection_name => ''PRODUCT_CHECK_FOR_PAY'');',
'    END IF;',
'',
'        ',
'',
'        for ii in (',
'                        ',
'               SELECT',
'    ',
'    product_id,',
'    id,',
'   ',
unistr('    SUM((case when item_ar_SA like ''%\0633\0639\0631 \0627\0644\0631\0628\062D%'' then nvl(item_totalPrice,0) else 0 end))   won_price,'),
unistr('    SUM((CASE WHEN item_ar_sa LIKE ''%\0633\0639\064A%''       THEN nvl( item_totalprice, 0) ELSE 0 END )) agent_price'),
'FROM',
'    TABLE ( get_sellerauctions_finance_data (apex_application.g_x04) ) WHERE  auctioncontainer_id = apex_application.g_x05',
'',
'    group by ',
'    product_id ,',
'    id',
'                  ',
'        )',
'          loop',
'',
'                    SELECT',
'                            COUNT(*) into  v_counts',
'                        FROM',
'                            apex_collections',
'                        WHERE',
'                            collection_name = ''PRODUCT_CHECK_FOR_PAY''',
'                            AND c001 = ii.product_id',
' ;',
'                            ',
'',
'                        if v_counts = 0 then ',
'',
'                          ',
'                            apex_collection.add_member(',
'                                                      p_collection_name => ''PRODUCT_CHECK_FOR_PAY'',',
'                                                      p_c001            => ii.product_id,',
'                                                      p_c002            => apex_application.g_x02,',
'                                                      p_c003            => apex_application.g_x03',
'                            );',
'',
'                        else',
'',
'',
'                                 SELECT',
'                                        seq_id',
'                                    INTO p_seq',
'                                    FROM',
'                                        apex_collections',
'                                    WHERE',
'                                        collection_name = ''PRODUCT_CHECK_FOR_PAY''',
'                                        AND c001 = ii.product_id ;',
'                        ',
'                                    apex_collection.update_member(',
'                                                                 p_collection_name => ''PRODUCT_CHECK_FOR_PAY'',',
'                                                                 p_seq             => p_seq,',
'                                                                 p_c001            => ii.product_id,',
'                                                                 p_c002            => apex_application.g_x02,',
'                                                                 p_c003            => apex_application.g_x03',
'                                    );',
'',
'                            end if;',
'',
'              ',
'',
'',
'         end loop ;    ',
'',
'',
' ',
'',
'',
'',
'',
'',
'',
'',
'',
'',
'      ',
'  ',
'',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>41245079582380247
);
end;
