,p_plug_display_sequence=>60
,p_query_type=>'FUNC_BODY_RETURNING_SQL'
,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare ',
'',
'v_Sub_Total number ;',
'v_Total_Discount number ;',
'v_Total_Price number ;',
'',
'begin',
'',
'',
'return q''~',
'    SELECT',
'    item_id ,',
'    item_ar_SA ,',
'    item_price ,',
'    item_quantity ,',
'    item_totalPrice ',
'                                                ',
'FROM',
'    TABLE ( get_sellerauctions_data(:P55_ID) ) WHERE  auctioncontainer_id = :P55_AUCTIONCONTAINER_ID AND auction_ID = :P55_PRODUCT_ID ',
'union ',
unistr('select 3  item_id ,''\0627\0644\0645\062C\0645\0648\0639 \0627\0644\0641\0631\0639\064A''         item_ar_SA  , null  item_price  ,  null  item_quantity, to_number(:P55_SUB_TOTAL  )     item_totalPrice  from dual '),
'union ',
unistr('select 2  item_id ,''\0625\062C\0645\0627\0644\064A \0627\0644\062E\0635\0645(\0627\0644\062A\0623\0645\064A\0646)''  item_ar_SA  , null  item_price  ,  null  item_quantity, to_number(:P55_TOTAL_DISCOUNT)  item_totalPrice  from dual '),
'union ',
unistr('select 1  item_id ,''\0627\0644\0633\0639\0631 \0627\0644\0643\0644\064A''            item_ar_SA   , null  item_price  ,  null  item_quantity, to_number(:P55_TOTAL_PRICE )    item_totalPrice  from dual '),
'',
'order by item_id desc',
' ',
'~'';',
'',
'',
'',
'',
'end;'))
,p_plug_source_type=>'NATIVE_IR'
,p_ajax_items_to_submit=>'P55_ID,P55_AUCTIONCONTAINER_ID,P55_PRODUCT_ID,P55_SUB_TOTAL,P55_TOTAL_DISCOUNT,P55_TOTAL_PRICE'
