,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(86236996114821533)
,p_plug_display_sequence=>40
,p_include_in_reg_disp_sel_yn=>'Y'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
' SELECT',
'    id,',
'    successfulproductscount,',
'    productscount,',
'    name,',
'    type,',
'    :P57_SELLER_ID SELLER_ID,',
'    -- iban_infath,',
'    auctioncontainer_id,',
'    sum(nvl(total_transfer,0)) total_transfer,',
'    sum(nvl(total_not_transfer,0)) total_not_transfer',
'   from (',
'SELECT distinct',
'    id,',
'    successfulproductscount,',
'    productscount,',
'    name,',
'    type,',
'    product_id,',
'    iban iban_infath,',
'    auctioncontainer_id,',
'    (case when istransfertoinfath = ''true'' and status LIKE ''%SOLD%'' then insurance else 0 end ) total_transfer,',
'    (case when transferreceiptno is null and status LIKE ''%SOLD%'' then insurance else 0 end ) total_not_transfer',
'FROM',
'    TABLE ( get_sellerauctions_data(:P57_SELLER_ID) ) ',
'      WHERE status LIKE ''%SOLD%'' and type like ''%INFATH%'' and  (id = :P57_AUCTIONS_ID or :P57_AUCTIONS_ID is null))',
'',
'',
'       group by id,',
'    successfulproductscount,',
'    productscount,',
'    name,',
'    type,',
'    -- iban_infath,',
'    auctioncontainer_id',
' '))
,p_lazy_loading=>true
,p_plug_source_type=>'NATIVE_CARDS'
,p_ajax_items_to_submit=>'P57_SELLER_ID,P57_AUCTIONS_ID'
,p_plug_query_num_rows_type=>'SCROLL'
,p_show_total_row_count=>false
);
