wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(106989352853513573)
,p_plug_name=>'Auctions Not Transfered'
,p_region_name=>'AuctionsNotTransfered'
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(86286645774821557)
,p_plug_display_sequence=>60
,p_include_in_reg_disp_sel_yn=>'Y'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT distinct',
'    -- s.totalcontainers,',
'    s.id auction_id,',
'    -- s.successfulproductscount,',
'    -- s.productscount,',
'    s.name,',
'    -- s.type,',
'    -- s.status,',
'    s.product_id,',
'    -- s.ar_sa,',
'    s.sakno Instrument_number,',
'    -- s.auctioncontainer_id,',
'    -- s.startprice,',
'    -- s.lastbid,',
'    -- s.paymentstatus,',
'    -- s.subtotal,',
'    -- s.totalprice,',
'    -- s.totaldiscount,',
'    -- s.buyer,',
'    (case when s.istransfertoinfath = ''true'' then ''rgba(0, 255, 0, .2)'' else ''rgba(255,228,181, .5)'' end ) color2,',
'    s.transferreceiptno transfer_receipt_no,',
'    s.transferdate Transfer_infath_date,',
'    s.infathurl infath_url,',
'    s.sadadinvoiceno sadad_receipt_no,',
'    s.sadadurl sadad_url,',
'    s.rechargedate Wallet_recharge_date,',
'    s.insurance deposit,',
'    s.iban iban_infath,',
'    -- s.item_id,',
'    -- s.item_ar_sa,',
'    -- s.item_price,',
'    -- s.item_quantity,',
'    -- s.item_totalprice,',
'    -- s.auction_id',
'    -- b.id,',
'    -- b.nidtype,',
'    s.nationalid ID_Number,',
'    s.buyer_name || '' ''||s.secondname || '' ''||s.thirdname|| '' ''||s.fourthname buyer,',
'    s.phone phone,',
'    -- b.dateofbirth,',
'    -- b.balance,',
'    -- b.active,',
'    -- b.country,',
'    -- b.buyertype,',
'    -- b.commissionername,',
'    -- b.commissionerphone,',
'    -- b.commissionernidtype,',
'    -- b.commissionernationalid,',
'    s.email E_mail,',
'    -- b.arfullname,',
'    -- b.enfullname,',
'    -- b.gender,',
'    -- b.arnationality,',
'    -- b.ennationality,',
'    -- b.dobg,',
'    -- b.encardissueplace',
'    null confirm,',
'    APEX_ITEM.CHECKBOX2(1,s.product_id || '':'' ||s.id,''UNCHECKED'' ) "SELECT"',
'FROM',
'    TABLE ( get_sellerauctions_finance_data(:p57_seller_id) ) s ',
'    -- join  TABLE ( get_buyers_data (:p57_seller_id)) b on  b.id = s.buyer',
'',
'     WHERE s.status = ''SOLD'' --and type like ''%INFATH%'' ',
'     and  (s.id = :P57_AUCTIONS_ID or :P57_AUCTIONS_ID is null) and s.transferreceiptno is null',
'',
'   and  not EXISTS',
'  (SELECT * FROM FINANCE_REVIEW_PRODUCTS e',
'    WHERE s.product_id ',
'    = e.product_id and s.id =e.AUCTION_ID )',
'   ',
'    --  and s.buyer = b.id',
'    -- auctioncontainer_id = :P15_AUCTIONCONTAINER_ID',
'    order by s.transferreceiptno desc'))
,p_plug_source_type=>'NATIVE_IR'
,p_ajax_items_to_submit=>'P57_SELLER_ID,P57_AUCTIONS_ID'
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
