 p_id=>wwv_flow_imp.id(48046417401998736)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'SEND EMAIL'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_result  NUMBER;',
'    v_task_id NUMBER;',
'    v_message VARCHAR2(255);',
'    v_email   VARCHAR2(500);',
'BEGIN',
' ',
'',
'',
'    -- SEND EMAIL',
'    BEGIN',
'        SELECT EMAIL INTO v_email',
'          FROM MOBASHER_EMPLOYEES',
'         WHERE DEPARTMENT_ID = :P3_DEPARTMENT_ID',
'           AND IS_MANAGER = 1;',
'    EXCEPTION',
'        WHEN NO_DATA_FOUND THEN',
'            v_email := ''a.awad@mobasher.sa'';',
'    END;',
'',
'    v_result := SYSTEM_CONTROLS.send_email ( ',
'                    p_to       => v_email,',
unistr('                    p_subject  => '' \0625\0634\0639\0627\0631 \0628\0625\0633\0646\0627\062F \0645\0647\0645\0629 \062C\062F\064A\062F\0629 | T-'' || LPAD(v_task_id, 4, 0),'),
'                    p_html     => :P3_NAME_AR,',
'                    p_message  => v_message',
'    );',
'',
'    IF v_result <> 1 THEN',
'        RAISE_APPLICATION_ERROR (-20002, v_message);',
'    END IF;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_type=>'NEVER'
,p_internal_uid=>31760285014748334
);
