,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT c.DOCUMENT_URL,',
'       CASE',
'      WHEN c.DOCUMENT_URL IS NOT NULL THEN',
'          ''<span class="fa fa-file-o" aria-hidden="true"></span>''',
'      ELSE ''''',
'      END AS DOCUMENT_CLASS,',
'       c.INSPECTION_URL,',
'       CASE',
'      WHEN c.INSPECTION_URL IS NOT NULL THEN',
'          ''<span class="fa fa-file-o" aria-hidden="true"></span>''',
'      ELSE ''''',
'      END AS INSPECTION_CLASS,',
'      c.DROWING_FILE_URL,',
'       CASE',
'      WHEN c.DROWING_FILE_URL IS NOT NULL THEN',
'          ''<span class="fa fa-file-o" aria-hidden="true"></span>''',
'      ELSE ''''',
'      END AS DROWING_FILE_CLASS,',
'      c.BURN_FILE_URL,',
'       CASE',
'      WHEN c.BURN_FILE_URL IS NOT NULL THEN',
'          ''<span class="fa fa-file-o" aria-hidden="true"></span>''',
'      ELSE ''''',
'      END AS BURN_FILE_CLASS,',
'      c.ACCIDENT_FILE_URL,',
'       CASE',
'      WHEN c.ACCIDENT_FILE_URL IS NOT NULL THEN',
'          ''<span class="fa fa-file-o" aria-hidden="true"></span>''',
'      ELSE ''''',
'      END AS ACCIDENT_FILE_CLASS',
'',
' FROM CAR_DETAILS c,',
'      PRODUCTS p,',
'      INDIVIDUAL_PORTABLE_REQUESTS i',
' WHERE p.ID = c.PRODUCT_ID',
'  AND  p.ID = i.PRODUCT_ID',
'  AND  i.ID = :P59_REQUEST_ID'))
