,p_name=>'transactions'
,p_parent_plug_id=>wwv_flow_imp.id(52490061993583188)
,p_template=>wwv_flow_imp.id(86296507817821564)
,p_display_sequence=>10
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_component_template_options=>'#DEFAULT#:t-Report--stretch:t-Report--altRowsDefault:t-Report--rowHighlight'
,p_display_point=>'SUB_REGIONS'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ROWNUM SERIAL,SELLER_NAME,BALANCE,CREDIT,DEBIT,INDCATION,ADD_BALANCE_DATE,DESCRIPTION,RECEIPT_URL,RECEIPT_NO,REFERENCE_RECEIPT_NO,PAYMENT_STATUS,PARTIAL_AMMOUNT,URL_CLASS',
'FROM (',
'SELECT ',
'    decode(:P_LANG, ''EN'', NAME_EN, NAME_AR) SELLER_NAME,',
'    ammount                                                   balance,',
'    CASE',
'        WHEN add_balance_type = LOOKUPS_MNT.lookup_detail_id_by_code(''Credit'', ''withdrawal_type'') THEN',
'            ammount',
'        ELSE',
'            0',
'    END                                                       credit,',
'    CASE',
'        WHEN add_balance_type = LOOKUPS_MNT.lookup_detail_id_by_code(''Debt'', ''withdrawal_type'') THEN',
'           ammount',
'        ELSE',
'            0',
'    END                                                       debit,',
'    CASE',
'        WHEN add_balance_type = LOOKUPS_MNT.lookup_detail_id_by_code(''Debt'', ''withdrawal_type'') THEN',
'           ''<span class="fa fa-plus" aria-hidden="true"></span>''',
'        ELSE',
'            ''<span aria-hidden="true" class="fa fa-minus"></span>''',
'    END                                                       indcation,',
'    to_char(add_balance_date, ''yyyy-mm-dd hh24:mi:ss'')        add_balance_date,',
'    -- decode(:P_LANG, ''EN'', DESC_EN, DESC_AR) DESCRIPTION ,',
'    DESC_AR DESCRIPTION ,',
'    RECEIPT_URL,',
'    RECEIPT_NO,',
'    REFERENCE_RECEIPT_NO,',
'    PAYMENT_STATUS,',
'    CASE WHEN PAYMENT_STATUS = LOOKUPS_MNT.lookup_detail_id_by_code(''Partially_paid'', ''Payment_status'') THEN',
'                 NVL(PARTIAL_AMMOUNT,0)',
'         ELSE null',
'     END PARTIAL_AMMOUNT,',
'    CASE',
'       WHEN RECEIPT_URL IS NOT NULL THEN',
'                ''<span class="fa fa-file-o"aria-hidden="true"></span>''',
'            ELSE ''''',
'            END AS URL_CLASS',
'    ',
'',
'',
'FROM',
'    SELLERS_WALLETS SW',
'    JOIN SELLERS     S ON S.ID = SW.SELLER_ID',
' ',
'WHERE  SW.SELLER_ID = :P60_SELLER_ID',
'    ORDER BY  add_balance_date     ASC , SW.ID ASC) ORDER BY ROWNUM DESC',
''))
,p_ajax_enabled=>'Y'
,p_ajax_items_to_submit=>'P60_SELLER_ID'
