,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'    SELECT  SUM(credit_ACC)OVER(PARTITION BY SELLER_ID  ORDER BY ID, add_balance_date) AS credit_ACC ,balance',
'FROM(',
' SELECT ',
'   S.ID SELLER_ID,SW.ID,',
'    ammount                                                   balance,',
'    CASE',
'        WHEN add_balance_type = LOOKUPS_MNT.lookup_detail_id_by_code(''Debt'', ''withdrawal_type'') THEN',
'            ammount',
'              WHEN add_balance_type = LOOKUPS_MNT.lookup_detail_id_by_code(''Credit'', ''withdrawal_type'') THEN',
'          - ammount',
'        ELSE',
'            0',
'    END                                                       credit_ACC,',
'    CASE',
'        WHEN add_balance_type = LOOKUPS_MNT.lookup_detail_id_by_code(''Debt'', ''withdrawal_type'') THEN',
'           ammount',
'        ELSE',
'            0',
'    END                                                       debit,',
'    to_char(add_balance_date, ''yyyy-mm-dd hh24:mi:ss'')        add_balance_date,',
'    -- decode(:P_LANG, ''EN'', DESC_EN, DESC_AR) DESCRIPTION  ',
'    DESC_AR DESCRIPTION  ',
'FROM',
'    SELLERS_WALLETS SW',
'    JOIN SELLERS     S ON S.ID = SW.SELLER_ID',
' ',
'WHERE  SW.SELLER_ID = :P60_SELLER_ID',
'    ORDER BY  add_balance_date     DESC     ,SW.ID desc',
')',
'order by add_balance_date  DESC ,ID desc',
''))
