wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(53995505165486436)
,p_name=>'P60_BALANCE'
,p_item_sequence=>30
,p_item_plug_id=>wwv_flow_imp.id(52490061993583188)
,p_use_cache_before_default=>'NO'
,p_prompt=>'Balance'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT  SUM(credit_ACC) credit_ACC ',
'FROM(',
' SELECT ',
'    CASE',
'        WHEN add_balance_type = LOOKUPS_MNT.lookup_detail_id_by_code(''Debt'', ''withdrawal_type'') THEN',
'            ammount',
'              WHEN add_balance_type = LOOKUPS_MNT.lookup_detail_id_by_code(''Credit'', ''withdrawal_type'') THEN',
'          - ammount',
'        ELSE',
'            0',
'    END                                                       credit_ACC',
'FROM',
'    SELLERS_WALLETS SW',
'    JOIN SELLERS     S ON S.ID = SW.SELLER_ID',
' ',
'WHERE  SW.SELLER_ID = :P60_SELLER_ID',
'    ORDER BY  add_balance_date     DESC     ,SW.SELLER_ID desc',
')'))
,p_source_type=>'QUERY'
,p_display_as=>'NATIVE_NUMBER_FIELD'
,p_cSize=>30
,p_begin_on_new_line=>'N'
,p_colspan=>2
,p_read_only_when_type=>'ALWAYS'
,p_field_template=>wwv_flow_imp.id(86367188900821603)
,p_item_template_options=>'#DEFAULT#'
,p_is_persistent=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'number_alignment', 'left',
  'virtual_keyboard', 'decimal')).to_clob
);
