wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(53994947898486431)
,p_process_sequence=>30
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'update paid product'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_exists BOOLEAN;',
'    l_Ammount number := nvl(:P60_AMMOUNT,0);',
'    l_Product_Ammount number :=0 ;',
'    l_Payment_status  number ;',
'    l_Recetpt_no  varchar2(150) ;',
'Begin',
'',
'        l_exists := APEX_COLLECTION.COLLECTION_EXISTS (',
'        p_collection_name => ''DISTRIBUTION_AMOUNT_COLLECTION'');',
'        IF l_exists THEN ',
'',
'            FOR I IN (SELECT  SEQ_ID   Sequence,',
'                              to_number(c001)    ID,',
'                              to_number(c008)    PAYMENT_STATUS,',
'                  ',
'                              case when to_number(c008) = LOOKUPS_MNT.lookup_detail_id_by_code(''Partially_paid'', ''Payment_status'') then',
'                                   to_number(c009)',
'                                   else ',
'                                   0              ',
'                                 end PARTIAL_AMMOUNT,',
'                              to_number(c009)   Product_Ammount_Payed ',
'                         FROM apex_collections',
'                         WHERE collection_name = ''DISTRIBUTION_AMOUNT_COLLECTION'' and to_number(c008) != LOOKUPS_MNT.lookup_detail_id_by_code(''Unpaid'', ''Payment_status''))',
'',
'',
'            LOOP ',
'    ',
'                UPDATE SELLERS_WALLETS ',
'                 SET PAYMENT_STATUS = I.PAYMENT_STATUS ,',
'                     PARTIAL_AMMOUNT = PARTIAL_AMMOUNT + i.PARTIAL_AMMOUNT ,',
'                     REFERENCE_RECEIPT_NO = case when REFERENCE_RECEIPT_NO is null then  :P60_RECEIPT_NO  else REFERENCE_RECEIPT_NO ||'':''||:P60_RECEIPT_NO end',
'            ',
'                 WHERE ID = I.ID;',
'    ',
'            END LOOP;',
'',
'            /*APEX_COLLECTION.TRUNCATE_COLLECTION(',
'                    p_collection_name => ''DISTRIBUTION_AMOUNT_COLLECTION'');*/',
'                    APEX_COLLECTION.DELETE_COLLECTION (',
'                        p_collection_name => ''DISTRIBUTION_AMOUNT_COLLECTION'');',
'   ',
'',
'',
'',
'        ELSE',
'               if :P60_AMMOUNT != 0 and :P60_AMMOUNT is not null  and :P60_ADD_BALANCE_TYPE = LOOKUPS_MNT.lookup_detail_id_by_code(''Debt'', ''withdrawal_type'') then',
'',
'                        for i in (select ID,',
'                           SELLER_ID,',
'                           AUCTION_ID,',
'                           PRODUCT_ID,',
'                           CONTRACT_ID,',
'                           CASE WHEN PAYMENT_STATUS = LOOKUPS_MNT.lookup_detail_id_by_code(''Partially_paid'', ''Payment_status'') THEN',
'                                     AMMOUNT - NVL(PARTIAL_AMMOUNT,0)',
'                                ELSE AMMOUNT ',
'                            END AMMOUNT,',
'                           ADD_BALANCE_TYPE,',
'                           ADD_BALANCE_DATE,',
'                           RECEIPT_NO,',
'                           RECEIPT_URL,',
'                           DESC_AR,',
'                           DESC_EN,',
'                           CREATED_DATE,',
'                           CREATED_BY,',
'                           MODIFIED_DATE,',
'                           MODIFIED_BY,',
'                           PAYMENT_STATUS,',
'                           REFERENCE_RECEIPT_NO',
'                      from SELLERS_WALLETS sw',
'                      where SELLER_ID = :P60_SELLER_ID and ADD_BALANCE_TYPE = LOOKUPS_MNT.lookup_detail_id_by_code(''Credit'', ''withdrawal_type'') ',
'                      and  PAYMENT_STATUS in ( LOOKUPS_MNT.lookup_detail_id_by_code(''Unpaid'', ''Payment_status''),LOOKUPS_MNT.lookup_detail_id_by_code(''Partially_paid'', ''Payment_status'') )',
'                       order by AUCTION_ID asc ,PRODUCT_ID asc ,ADD_BALANCE_DATE asc )',
'',
'',
'                      loop',
'',
'                            if i.AMMOUNT <= l_Ammount then ',
'',
'                                 l_Payment_status := LOOKUPS_MNT.lookup_detail_id_by_code(''paid'', ''Payment_status'') ;',
'                                 l_Ammount := l_Ammount - i.AMMOUNT ;',
'                                 l_Recetpt_no := :P60_RECEIPT_NO ;',
'',
'                            elsif i.AMMOUNT > l_Ammount and l_Ammount != 0  then ',
'',
'                                l_Payment_status := LOOKUPS_MNT.lookup_detail_id_by_code(''Partially_paid'', ''Payment_status'') ;',
'                                l_Product_Ammount := l_Ammount ;',
'                                l_Ammount := 0 ;',
'                                l_Recetpt_no := :P60_RECEIPT_NO ;',
'',
'                            else ',
'                                l_Payment_status := LOOKUPS_MNT.lookup_detail_id_by_code(''Unpaid'', ''Payment_status'') ;',
'                                l_Recetpt_no := null ;',
'                            end if ;',
'                      ',
'',
'                              UPDATE SELLERS_WALLETS ',
'                                SET PAYMENT_STATUS = l_Payment_status ,',
'                                    PARTIAL_AMMOUNT = PARTIAL_AMMOUNT + l_Product_Ammount ,',
'                                    REFERENCE_RECEIPT_NO = case when REFERENCE_RECEIPT_NO is null then  l_Recetpt_no  else REFERENCE_RECEIPT_NO ||'':''||l_Recetpt_no end',
'            ',
'                                WHERE ID = I.ID;',
'',
'',
'                      end loop ; ',
'',
'               end if;',
'        END IF;',
'',
'End;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(52504499369583165)
,p_internal_uid=>37708815511236029
);
