'    -- s.ar_sa,',
'    nvl(s.sakno,s.ar_sa) Instrument_number,',
'    -- s.auctioncontainer_id,',
'    -- s.startprice,',
'    -- s.lastbid,',
'    -- s.paymentstatus,',
'    -- s.subtotal,',
'    -- s.totalprice,',
'    -- s.totaldiscount,',
'    -- s.buyer,',
'    (case when s.istransfertoinfath = ''true'' then ''rgba(0, 255, 0, .2)'' else ''rgba(255,228,181, .5)'' end ) color,',
'    s.transferreceiptno transfer_receipt_no,',
'    s.transferdate Transfer_infath_date,',
'    s.infathurl infath_url,',
'    s.sadadinvoiceno sadad_receipt_no,',
'    s.sadadurl sadad_url,',
'    s.rechargedate Wallet_recharge_date,',
'    s.insurance deposit,',
'    s.iban iban_infath,',
'    -- s.item_id,',
'    -- s.item_ar_sa,',
'    -- s.item_price,',
'    -- s.item_quantity,',
'    -- s.item_totalprice,',
'    -- s.auction_id',
'    -- b.id,',
'    -- b.nidtype,',
'    s.nationalid ID_Number,',
'    s.buyer_name || '' ''||s.secondname || '' ''||s.thirdname|| '' ''||s.fourthname buyer,',
'    s.phone phone,',
'    -- b.dateofbirth,',
'    -- b.balance,',
'    -- b.active,',
'    -- b.country,',
'    -- b.buyertype,',
'    -- b.commissionername,',
'    -- b.commissionerphone,',
'    -- b.commissionernidtype,',
'    -- b.commissionernationalid,',
'    s.email E_mail--,',
'    -- b.arfullname,',
'    -- b.enfullname,',
'    -- b.gender,',
'    -- b.arnationality,',
'    -- b.ennationality,',
'    -- b.dobg,',
'    -- b.encardissueplace',
'FROM',
'    TABLE ( get_sellerauctions_finance_data(:p63_seller_id) ) s ',
'    -- join  TABLE ( get_buyers_data (:p63_seller_id)) b on  b.id = s.buyer',
'',
'     WHERE s.status = ''SOLD'' and type like ''%INFATH%'' and s.id = :P63_AUCTIONS_ID ',
'    --  and s.buyer = b.id',
'    -- auctioncontainer_id = :P15_AUCTIONCONTAINER_ID',
'    order by s.transferreceiptno desc'))
