wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(57567384159962737)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'SEND EMAIL'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_result  NUMBER;',
'    v_task_id NUMBER;',
'    v_message VARCHAR2(255);',
'    v_email   VARCHAR2(500);',
'BEGIN',
' ',
'',
'',
'    -- SEND EMAIL',
'    BEGIN',
'        SELECT EMAIL INTO v_email',
'          FROM MOBASHER_EMPLOYEES',
'         WHERE DEPARTMENT_ID = :P3_DEPARTMENT_ID',
'           AND IS_MANAGER = 1;',
'    EXCEPTION',
'        WHEN NO_DATA_FOUND THEN',
'            v_email := ''a.awad@mobasher.sa'';',
'    END;',
'',
'    v_result := SYSTEM_CONTROLS.send_email ( ',
'                    p_to       => v_email,',
unistr('                    p_subject  => '' \0625\0634\0639\0627\0631 \0628\0625\0633\0646\0627\062F \0645\0647\0645\0629 \062C\062F\064A\062F\0629 | T-'' || LPAD(v_task_id, 4, 0),'),
'                    p_html     => :P3_NAME_AR,',
'                    p_message  => v_message',
'    );',
'',
'    IF v_result <> 1 THEN',
'        RAISE_APPLICATION_ERROR (-20002, v_message);',
'    END IF;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_type=>'NEVER'
,p_internal_uid=>41281251772712335
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(57568228755962737)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Confirm_All_Data'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare ',
' l_buf varchar2(100) ;',
' l_PRODUCT_ID number;',
' l_AUCTION_ID number;',
'',
'',
'      ',
'',
'begin',
'       IF APEX_APPLICATION.G_F01.COUNT = 0 THEN',
'',
'            apex_error.add_error (',
'',
'            p_message          => ''Please select some rows'',',
'',
'            p_display_location =>  apex_error.c_inline_with_field_and_notif,',
'',
'            p_page_item_name   => ''P63_SELLER_ID''',
'            );',
'            ',
'',
'        else ',
'',
'',
'        ',
'',
'',
'        FOR I in 1..APEX_APPLICATION.G_F01.COUNT LOOP',
'               ',
'                l_buf := apex_application.g_f01(i);',
'                l_PRODUCT_ID := to_number(substr(l_buf, 1, instr(l_buf,'':'')-1));',
'                l_AUCTION_ID := to_number(substr(l_buf, instr(l_buf,'':'')+1));',
'',
'                insert into finance_Review_Products(auction_ID , Product_ID ) values (l_AUCTION_ID,l_PRODUCT_ID) ;',
'',
'            END LOOP;',
'',
'            -- (select COLUMN_VALUE from TABLE(apex_string.split(apex_application.g_f01(i) ,'':'')))',
'            -- SELECT LISTAGG(ID, '':'') WITHIN GROUP (ORDER BY ID) into l_buf FROM user to_number(APEX_APPLICATION.G_F01(i))',
'',
'',
'',
'        END IF;',
'',
'            ',
'          ',
'          ',
'     ',
'',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>41282096368712335
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(57567759009962737)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Confirm_Data'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    v_value varchar2(100);',
'begin',
'v_value :=apex_application.g_x01 ;',
'',
'   apex_json.open_object;',
'      apex_json.write(''hi'', ''hi'');',
'      apex_json.write(''value'', v_value);',
'',
'',
'     insert into finance_Review_Products(auction_ID , Product_ID ) values (apex_application.g_x02,apex_application.g_x01) ;',
'',
'',
'',
'',
'    ',
'      apex_json.write(''massege'', ''done'');',
'   apex_json.close_all;',
'   ',
'end;',
''))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>41281626622712335
);
end;
