wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(54241803124364607)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_region_id=>wwv_flow_imp.id(54221618489364629)
,p_process_type=>'NATIVE_IG_DML'
,p_process_name=>'Review - Save Interactive Grid Data'
,p_attribute_01=>'PLSQL_CODE'
,p_attribute_04=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'',
'l_PAYMENT_STATUS number ;',
'',
'begin',
'',
'',
'',
'     case :APEX$ROW_STATUS',
'         when ''C'' then',
'     ',
'            NULL;',
'         when ''U'' then',
'',
'',
'                 if to_number(:PRODUCT_AMMOUNT_PAYED ) < to_number(:AMMOUNT) and to_number(:PRODUCT_AMMOUNT_PAYED ) != 0  then ',
'                      l_PAYMENT_STATUS :=   LOOKUPS_MNT.lookup_detail_id_by_code(''Partially_paid'', ''Payment_status'') ;',
'                 elsif :PRODUCT_AMMOUNT_PAYED = 0  then ',
'                      l_PAYMENT_STATUS :=  LOOKUPS_MNT.lookup_detail_id_by_code(''Unpaid'', ''Payment_status'');',
'                 elsif :PRODUCT_AMMOUNT_PAYED = :AMMOUNT   then ',
'                      l_PAYMENT_STATUS :=  LOOKUPS_MNT.lookup_detail_id_by_code(''paid'', ''Payment_status'');',
'                 else   ',
unistr('                      RAISE_APPLICATION_ERROR(-20001, ''\063A\064A\0631 \0645\0633\0645\0648\062D \064A\062C\0628 \0627\0646 \064A\0643\0648\0646 \0627\0644\0645\062F\0641\0648\0639 \0627\0642\0644 \0645\0646 \0627\0648 \064A\0633\0627\0648\064A \0645\0628\0644\063A \0627\0644\0633\0639\064A \0627\0648 \064A\0633\0627\0648\064A \0635\0641\0631 (0)'');'),
'                 end if ;',
'                 APEX_COLLECTION.UPDATE_MEMBER (',
'                                  p_collection_name => ''DISTRIBUTION_AMOUNT_COLLECTION'',',
'                                  p_seq             => :SEQUENCE,',
'                                  p_c001            => :ID,',
'                                  p_c002            => :SELLER_ID,',
'                                  p_c003            => :AUCTION_ID,',
'                                  p_c004            => :PRODUCT_ID,',
'                                  p_c005            => :AMMOUNT,',
'                                  p_c006            => :DESC_AR,',
'                                  p_c007            => :ADD_BALANCE_DATE,',
'                                  p_c008            => l_PAYMENT_STATUS,',
'                                  p_c009            => :PRODUCT_AMMOUNT_PAYED',
'                   );',
'         when ''D'' then',
'            NULL;',
'    end case;   ',
'',
'end;'))
,p_attribute_05=>'N'
,p_attribute_06=>'N'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_only_for_changed_rows=>'N'
,p_internal_uid=>37955670737114205
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(53994118635486422)
,p_process_sequence=>30
,p_process_point=>'AFTER_SUBMIT'
,p_region_id=>wwv_flow_imp.id(54221618489364629)
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'check total ammount'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'',
'l_AMMOUNT number ;',
'',
'begin',
'',
'',
'    SELECT  sum (to_number(nvl(c009,0)) ) into l_AMMOUNT',
'        FROM apex_collections',
'        WHERE collection_name = ''DISTRIBUTION_AMOUNT_COLLECTION'' ;',
'   ',
'',
'    if  l_AMMOUNT <= to_number(:P64_AMMOUNT)  then ',
'',
'     null;',
'    else ',
'      ',
unistr('       RAISE_APPLICATION_ERROR(-20001, '' \064A\062C\0628 \0627\0646 \064A\0643\0648\0646 \0627\0644\0645\0633\062F\062F \0627\0642\0644 \0645\0646 \0627\0648 \064A\0633\0627\0648\064A \0642\064A\0645\0629 \0627\0644\0641\0627\062A\0648\0631\0647 ''||to_number(:P64_AMMOUNT));'),
'    end if ;',
'',
'   end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_only_for_changed_rows=>'N'
,p_internal_uid=>37707986248236020
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(53992580963486407)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Distribution Amount'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
' DECLARE',
'    l_exists BOOLEAN;',
'    l_AMMOUNT number ;',
'Begin',
'',
'        l_exists := APEX_COLLECTION.COLLECTION_EXISTS (',
'        p_collection_name => ''DISTRIBUTION_AMOUNT_COLLECTION'');',
'        IF l_exists THEN ',
'',
'            SELECT  sum (to_number(NVL(c009,0)) ) into l_AMMOUNT',
'                FROM apex_collections',
'                WHERE collection_name = ''DISTRIBUTION_AMOUNT_COLLECTION'' ;',
'   ',
'',
'                if l_AMMOUNT != :P64_AMMOUNT then ',
'                  APEX_COLLECTION.TRUNCATE_COLLECTION(',
'                    p_collection_name => ''DISTRIBUTION_AMOUNT_COLLECTION'');',
'                else ',
'                  null ;',
'                end if ;',
'',
'',
'        ELSE',
'          APEX_COLLECTION.CREATE_COLLECTION(',
'          p_collection_name => ''DISTRIBUTION_AMOUNT_COLLECTION'');',
'       END IF;',
'',
'End;',
'',
'',
'',
'--------------------------------------------------------------------------',
'',
'DECLARE',
'    l_Ammount number := nvl(:P64_AMMOUNT,0);',
'    l_Product_Ammount number ;',
'    l_Payment_status  number ;',
'BEGIN',
'',
'    for i in (select ID,',
'       SELLER_ID,',
'       AUCTION_ID,',
'       PRODUCT_ID,',
'       CONTRACT_ID,',
'       CASE WHEN PAYMENT_STATUS = LOOKUPS_MNT.lookup_detail_id_by_code(''Partially_paid'', ''Payment_status'') THEN',
'                 AMMOUNT - NVL(PARTIAL_AMMOUNT,0)',
'            ELSE AMMOUNT ',
'        END AMMOUNT,',
'       ADD_BALANCE_TYPE,',
'       ADD_BALANCE_DATE,',
'       RECEIPT_NO,',
'       RECEIPT_URL,',
'       DESC_AR,',
'       DESC_EN,',
'       CREATED_DATE,',
'       CREATED_BY,',
'       MODIFIED_DATE,',
'       MODIFIED_BY,',
'       PAYMENT_STATUS',
'  from SELLERS_WALLETS sw',
'  where SELLER_ID = :P64_SELLER_ID and ADD_BALANCE_TYPE = LOOKUPS_MNT.lookup_detail_id_by_code(''Credit'', ''withdrawal_type'') ',
'  and NOT EXISTS (',
'        SELECT',
'            c001',
'        FROM',
'            apex_collections',
'        WHERE',
'           collection_name = ''DISTRIBUTION_AMOUNT_COLLECTION'' and c001 = sw.id )',
'  and  PAYMENT_STATUS in ( LOOKUPS_MNT.lookup_detail_id_by_code(''Unpaid'', ''Payment_status''),LOOKUPS_MNT.lookup_detail_id_by_code(''Partially_paid'', ''Payment_status'') )',
'   order by AUCTION_ID asc ,PRODUCT_ID asc )',
'',
'',
'  loop',
'',
'        if i.AMMOUNT <= l_Ammount then ',
'             l_Payment_status := LOOKUPS_MNT.lookup_detail_id_by_code(''paid'', ''Payment_status'') ;',
'             l_Ammount := l_Ammount - i.AMMOUNT ;',
'             l_Product_Ammount := i.AMMOUNT ;',
'',
'        elsif i.AMMOUNT > l_Ammount and l_Ammount != 0  then ',
'',
'             l_Payment_status := LOOKUPS_MNT.lookup_detail_id_by_code(''Partially_paid'', ''Payment_status'') ;',
'             l_Product_Ammount := l_Ammount ;',
'             l_Ammount := 0 ;',
'',
'        else ',
'             l_Payment_status := LOOKUPS_MNT.lookup_detail_id_by_code(''Unpaid'', ''Payment_status'') ;',
'             l_Product_Ammount := 0 ;',
'        end if ;',
'  ',
'',
'   APEX_COLLECTION.ADD_MEMBER (',
'            p_collection_name => ''DISTRIBUTION_AMOUNT_COLLECTION'',',
'            p_c001            => i.ID,',
'            p_c002            => i.SELLER_ID,',
'            p_c003            => i.AUCTION_ID,',
'            p_c004            => i.PRODUCT_ID,',
'            p_c005            => i.AMMOUNT,',
'            p_c006            => i.DESC_AR,',
'            p_c007            => i.ADD_BALANCE_DATE,',
'            p_c008            => l_Payment_status,',
'            p_c009            => l_Product_Ammount',
'        );',
'',
'',
'  end loop ; ',
'  ',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>37706448576236005
);
end;
/
